/* AYT matematik 121–240: soru bazında çözüm, kaynak incelemesi ve özgün aktarım soruları. */
(() => {
 const all=window.EXAM_ANALYSES=window.EXAM_ANALYSES||{};
 function add(n,title,topic,book,page,tests,knowledge,reasoning,trap,concept,why,stem,options,answer,explanation,resolvedAnswer){
  all[`q-ayt-matematik-${String(n).padStart(3,'0')}`]={title,topic,lessonIds:[],studyRefs:[{book,page,title:topic}],tests,knowledge,reasoning,trap,connections:[{concept,why}],variation:{stem,options,answer,explanation},status:'reviewed',keyCheck:'matches',resolvedAnswer,note:''};
 }
 add(121,'İki film zincirini araya yerleştirme','Kombinasyon','TYT-mat',74,
 'Her serideki zorunlu1–2–3 sırasını koruyarak iki zincirin altı farklı akşama kaç biçimde karışabileceğini ölçer.',
 ['A serisinin üç akşamı seçilince A filmleri o akşamlara tek biçimde kronolojik yerleşir.','Kalan üç akşam da B serisinin sırasını tek biçimde belirler; seriler arası bir öncelik yoktur.'],
 ['Altı akşamdan A için üç yer seç: C(6,3)=20.','A yerlerine A₁,A₂,A₃ ve kalanlara B₁,B₂,B₃ yazılır. Başka çarpan eklenmez; doğru seçenek A’dır.'],
 '6! saymak serilerin kendi içindeki yasak sıralarını dahil eder; C(6,3)’ü ayrıca3! ile çarpmak da aynı hatayı geri getirir.',
 'Kısmi sıralama','İki öncelik zincirinin birleşimi, her zincir için yerleri seçmekle sayılır; zincir içi düzen sabittir.',
 'İki filmlik A ve üç filmlik B serilerinin sırası korunarak beş akşam kaç biçimde düzenlenir?',['5','8','10','12','20'],2,'A için beş yerden iki seçilir: C(5,2)=10. Her iki seri kendi seçilen yerlerine tek biçimde yerleşir.','A');
 add(122,'Erken çıkan arabayı engellememe','Kısıtlı permütasyon','TYT-mat',72,
 'Duvara bakan üç çiftli park sütununda çıkış saatlerinin oluşturduğu geçerli tür yerleşimlerini gerçek arabaların permütasyonundan ayırmayı ölçer.',
 ['Her sütunda13.00 arabası önde,18.00 arabası arkada olamaz.','Bir sütundaki erken araba sayısı0,1 veya2 olabilir;bir tane varsa arkadaki konumda olmalıdır.'],
 ['Üç erken arabanın sütun dağılımları(1,1,1) veya(2,1,0)’ın altı permütasyonudur;toplam7 tür düzeni vardır.','Her düzende erken arabalar3!,geç arabalar3! biçimde yerleşir.7×6×6=252,cevap B’dir.'],
 'Her sütunun iki farklı çıkış saati içermesi gerektiğini varsaymak iki erken veiki geç arabanın aynı sütunda olabildiği altı düzeni dışlar.',
 'Tür ve kimlik sayımı','Önce saat etiketleri,sonra aynı etiketteki farklı arabalar yerleştirilirse engelleme koşulu kolay denetlenir.',
 'İki erken veiki geç araba iki çiftli sütuna aynı kuralla yerleştirilirse kaç düzen vardır?',['4','8','12','16','24'],2,'Erken sayısı dağılımları(1,1),(2,0),(0,2) olmak üzere3 tanedir. Her birinde2!×2!=4 kimlik yerleşimi vardır;toplam12’dir.','B');
 add(123,'Bağımsızlıktan eksik yemek sayısı','Bağımsız olaylar','AYT-mat',27,
 'Etli ve acılı olaylarının bağımsızlığını etli-acılı kesişiminin olasılığıyla birleştirip bütün acılı yemek sayısını bulmayı ölçer.',
 ['Etli yemek sayısı8+6=14 ve P(E)=14/35’tir.','Bağımsızlık P(E∩A)=P(E)P(A) eşitliğidir;verilen kesişim8/35’tir.'],
 ['8/35=(14/35)P(A) eşitliğinden P(A)=4/7 bul.','Acılı yemekler35×4/7=20 tanedir. Sekizi etli olduğundan etsiz-acılı20−8=12,cevap E’dir.'],
 'Bağımsız olayları ayrık saymak kesişimin sıfır olması gerektiğini düşündürür;burada sekiz ortak yemek bulunması bağımsızlığa engel değildir.',
 'Koşullu olasılık','Etli yemeklerde acılı oranı8/14,bağımsızlık nedeniyle bütün menüdeki acılı oranına eşittir.',
 '40 yemekten16’sı etli,8’i etli-acılı ve olaylar bağımsızsa toplam acılı kaçtır?',['12','16','18','20','24'],3,'P(acılı)=8/16=1/2’dir. Bütün40 yemek içinde20 acılı bulunur.','E');
 add(124,'Binomda y üssünü seçme','Binom açılımı','TYT-mat',77,
 '(x²+2y)⁷ açılımında y² koşulunun ikinci terimden tam iki seçim gerektirdiğini kullanıp x üssü ile katsayıyı ayırmayı ölçer.',
 ['Genel terim C(7,k)(x²)^(7−k)(2y)^k biçimindedir.','y üssü k olduğundan k=2 seçilir; x üssü2(7−2)=10’dur.'],
 ['Katsayı m=C(7,2)2²=21×4=84 bulunur.','n=10 olduğundan m+n=94’tür. Doğru seçenek E’dir;katsayıya x üssü dahil edilmez.'],
 '2y ifadesindeki2’yi yalnız bir kez çarpmak(2y)² içindeki4 çarpanını kaçırır ve katsayıyı yarıya indirir.',
 'Seçim ve üs dağılımı','Binom katsayısı hangi çarpanlarda y’nin seçildiğini,kalan üsler ise her seçimden kalan x sayısını verir.',
 '(x²+3y)⁵ açılımında y²’li terimin x üssü kaçtır?',['2','3','4','6','8'],3,'İki çarpandan y seçilir,kalan üç çarpandan x² gelir. Toplam x üssü2×3=6 olur.','E');
 add(125,'Katsayı ortalamasından açılım derecesi','Binom açılımı','TYT-mat',77,
 'Katsayılar toplamını x=1 ile bulup farklı üslerin n+1 terim oluşturmasını kullanarak n’yi ve hedef katsayıyı hesaplamayı ölçer.',
 ['(x³−2/x²)ⁿ için katsayı toplamı(1−2)ⁿ=(−1)ⁿ’dir.','Üsler3n−5k biçiminde farklı olduğundan terim sayısı n+1’dir;aritmetik ortalama toplam/(n+1) olur.'],
 ['(−1)ⁿ/(n+1)=1/5 pozitif olduğundan n çift ve n+1=5,n=4’tür.','12−5k=2 için k=2;C(4,2)(−2)²=24 bulunur. Doğru seçenek C’dir.'],
 'Ortalama0,2’yi katsayı toplamı sanmak terim sayısına bölmeyi unutur;negatif üsler de ayrı açılım terimleridir.',
 'Katsayı toplamı','x=1 bütün x kuvvetlerini1 yapar;Laurent biçimindeki negatif üsler için de bu değerlendirme geçerlidir.',
 '(x²−2/x)⁴ açılımının katsayılar toplamı kaçtır?',['−16','−1','0','1','16'],3,'x=1 konulduğunda(1−2)⁴=1 bulunur. Negatif terimlerin işaretleri toplam içinde korunur.','C');
 add(126,'Simetrik binom katsayılarının oranı','Binom açılımı','TYT-mat',77,
 '(x+a/x)¹⁰ açılımında x⁻² ve x² terimlerinin simetrik seçim sayılarını kullanıp oranı yalnız a kuvvetine indirmeyi ölçer.',
 ['Genel x üssü10−2k,katsayı C(10,k)a^k’dir.','x⁻² için k=6,x² için k=4 gerekir ve C(10,6)=C(10,4)’tür.'],
 ['Katsayı oranını a⁶/a⁴=a² olarak yaz.','Verilen oran16 olduğundan a²=16;pozitiflik a=4’ü seçtirir. Doğru seçenek C’dir;negatif a dalı alınmaz.'],
 'x üssündeki eksi işaretini katsayının da eksi olması sanmak yanlıştır;a pozitif ve açılım toplama içerdiğinden katsayılar pozitiftir.',
 'Kombinasyon simetrisi','On seçimde altı ikinci terim seçmek,dört birinci terim seçmekle aynı sayıda konum düzeni verir.',
 '(x+a/x)⁸ açılımında x⁻² katsayısının x² katsayısına oranı nedir?',['a','a²','a³','1/a','1/a²'],1,'İndisler5 ve3’tür;C(8,5)=C(8,3). Oran a⁵/a³=a² olur.','C');
 add(127,'Tek seçimli terimden parametre','Binom açılımı','TYT-mat',77,
 'On üçüncü kuvvet açılımında x¹¹ üssünün ikinci terimin bir kez seçilmesiyle oluştuğunu görüp verilen rasyonel katsayı eşitliğini çözmeyi ölçer.',
 ['(x+(a−7)/x)¹³ genel teriminin üssü13−2k’dir.','13−2k=11 için k=1,katsayı13(a−7) olur.'],
 ['13(a−7)=234/a eşitliğini a≠0 ile çarp ve a²−7a−18=0 bul.','(a−9)(a+2)=0’dan pozitif a=9 kalır. Doğru seçenek A’dır;katsayıda a−7 parantezi bütündür.'],
 'İkinci terimi a−7/x diye okumak kesrin payındaki parantezi bozarak farklı açılım üretir;görselde a−7 birlikte x’e bölünür.',
 'Üs denklemi','Önce hedef üsten seçim indisi bulunur;parametre katsayıya ancak bundan sonra yerleştirilir.',
 '(x+c/x)⁹ açılımında x⁷ katsayısı18 ise c kaçtır?',['1','2','3','4','9'],1,'9−2k=7’den k=1 gelir;katsayı9c=18 olduğundan c=2’dir.','A');
 add(128,'Sabit katsayının5-adik sınırlaması','Binom açılımı','TYT-mat',77,
 'Sabit terim koşulunda katsayı C(n,k)5^k=60 olduğundan ikinci terimin ancak bir kez seçilebileceğini kullanmayı ölçer.',
 ['Genel terimin x üssü n−(m+1)k,katsayısı C(n,k)5^k’dir.','k≥2 olursa katsayı25’in katı olur;60,25’e bölünmez. k=0 ise katsayı1’dir.'],
 ['Bu yüzden k=1 ve5n=60,n=12 bulunur.','Sabitlik12−(m+1)=0’dan m=11 verir. m+n=23,cevap E’dir;iki bilinmeyen farklı koşullardan belirlenir.'],
 'Sabit terimde x görünmediği için tüm kuvvetleri sıfır seçmek k=0’a götürür;önce üslerin birbirini götürmesi gerekir.',
 'Asal çarpan ve kombinasyon','Katsayının içerdiği5 kuvveti seçim sayısına sınır koyar;aritmetik bölünebilme binom indisini belirler.',
 '(x+5/x^m)¹² açılımında k=1 terimi sabitse m kaçtır?',['5','6','10','11','12'],3,'Bir ikinci terim seçilince x üssü11−m’dir. Sabit olması m=11 gerektirir.','E');
 add(129,'Eşit katsayılarda simetrik indisler','Binom açılımı','TYT-mat',77,
 'Farklı iki x üssünün aynı binom katsayısını taşımasını indislerin n’ye tamamlanmasıyla ilişkilendirip n ve k’yi bulmayı ölçer.',
 ['(x²+x)ⁿ teriminde x üssü2n−j,katsayı C(n,j)’dir.','İstenen indisler j₁=3n−19,j₂=3n−16’dır;farklı eşit binom katsayılarında j₁+j₂=n olur.'],
 ['6n−35=n eşitliğinden n=7 bul.','İndisler2 ve5’tir;C(7,2)=C(7,5)=21. Ortak katsayı k=21,cevap E’dir;indislerin0–7 aralığında olduğu da sağlanır.'],
 'Üsleri19 ve16 sanmak üstteki−n kısmını atlar;özgün görselde19−n ve16−n birer tam üst ifadesidir.',
 'Pascal satırı simetrisi','Bir satırdaki katsayılar ortanın iki yanında eşittir;farklı iki hedef terim bu simetriyle bağlanır.',
 'C(9,2) ile eşit ve indisi2’den farklı katsayı hangisidir?',['C(9,3)','C(9,4)','C(9,5)','C(9,6)','C(9,7)'],4,'C(n,r)=C(n,n−r) olduğundan9−2=7 indisi aynı değeri verir.','E');
 add(130,'İki sabit terimde işaret farkı','Binom açılımı','TYT-mat',77,
 'Farklı x kuvvetleri taşıyan iki açılımda sabitlik indislerini ayrı bulup tek ve çift kuvvetlerin katsayı işaretini izlemeyi ölçer.',
 ['İlk açılımın x üssü24−3k’dir;sabit terim k=8,C(12,8)a⁸=495a⁸ olur.','İkincide üs36−4k’dir;k=9 ve(−a)⁹ nedeniyle sabit terim−220a⁹’dur.'],
 ['Toplam495a⁸−220a⁹=a⁸(495−220a)=0 yaz.','a≠0 olduğundan a=495/220=9/4 bulunur. Doğru seçenek E’dir;iki açılımda aynı seçim indisi kullanılmaz.'],
 'İkinci açılımda eksi işaretini k çiftmiş gibi pozitif almak toplamın sıfır olmasını engeller;burada k=9 tektir.',
 'Ortak çarpan','Yüksek kuvvetli parametre denklemi a⁸ dışarı alınınca tek doğrusal koşula iner;sıfır yasağı bölmeye izin verir.',
 '6a⁴−2a⁵=0 ve a≠0 ise a kaçtır?',['1','2','3','4','6'],2,'a⁴(6−2a)=0 eşitliğinde a⁴ sıfır olamaz.6−2a=0’dan a=3 bulunur.','E');
 add(131,'Dörtyüzlüde iki karıncanın karşılaşması','Basit olasılık','TYT-mat',80,
 'Her köşenin üç komşusu olduğu düzgün dörtyüzlüde9 eş olasılıklı ayrıt seçimini,aynı hedef ve ortak ayrıt olaylarına ayırmayı ölçer.',
 ['K ve L’den üçer ayrıt seçilir;toplam3×3=9 sıralı seçim vardır.','Karıncalar iki diğer köşeden aynı birine giderse orada karşılaşır;K–L ayrıtında birbirlerine giderlerse yol üzerinde karşılaşırlar.'],
 ['Ortak hedef için iki,doğrudan K↔L seçimi için bir uygun durum say.','Farklı diğer ayrıtlar üç boyutta kesişmez. Olasılık3/9=1/3,cevap A’dır;yalnız köşe buluşmaları sayılmaz.'],
 'Karşılaşmayı yalnız aynı varış köşesine ulaşmak sanmak K–L ayrıtında karşılıklı yürümeyi dışlar ve2/9 verir.',
 'Çizge modeli','Dörtyüzlü dört köşenin her ikisinin bağlı olduğu bir çizgedir;ayrıt seçimlerini hedef köşe seçimleriyle eşlemek sayımı kolaylaştırır.',
 'İki karınca farklı K,L köşelerinde;yalnız diğer aynı köşede bitirme olasılığı kaçtır?',['1/9','2/9','1/3','4/9','2/3'],1,'İki ortak hedef köşe vardır;her hedef için bir sıralı ayrıt seçimi olmak üzere2 uygun durum,toplam9 durum bulunur.','A');
 add(132,'Geri koymadan üçüncüde hedef bulma','Olasılık','TYT-mat',80,
 'Yanlış kartların geri konmadığı aramada ilk iki yanlış ve üçüncü doğru çekilişin koşullu çarpımını kurmayı ölçer.',
 ['İlk çekilişte yanlış kart olasılığı3/4’tür.','İlk yanlış elde tutulduğunda ikinci yanlış2/3,iki yanlış tutulduğunda doğru1/2 olasılıkla gelir.'],
 ['Olay sırasını yanlış–yanlış–otobüs olarak yaz.','3/4×2/3×1/2=1/4 bulunur. Doğru seçenek A’dır;eşdeğer olarak otobüs kartının rastgele sıralamadaki dört konumu eş olasılıklıdır.'],
 'Her çekilişte doğru olasılığını1/4 almak geri koyma varmış gibi davranır;çantadaki kart sayısı her yanlışta azalır.',
 'Rastgele sıralama','Geri koymadan arama,kartların rastgele bir permütasyonunu okumaktır;hedef kartın her sıra konumu eş olasılıklıdır.',
 'Beş farklı karttan hedef kartın dördüncü sırada bulunma olasılığı kaçtır?',['1/5','1/4','2/5','3/5','4/5'],0,'Rastgele sıralamada hedef kart beş konumun her birinde eş olasılıkla bulunur. Dördüncü konum olasılığı1/5’tir.','A');
 add(133,'Beş seçilmiş soruda bölüm dengesi','Olasılık ve kombinasyon','TYT-mat',80,
 'Toplam beş doğru içinde her iki bölümden en aziki olması koşulunu2–3 ve3–2 dağılımlarına ayırmayı ölçer.',
 ['Sekiz sorudan rastgele beşli seçimin sayısı C(8,5)=56’dır.','Geçerli dağılımlar sözel2,sayısal3 veya sözel3,sayısal2’dir;4–1 ve1–4 geçersizdir.'],
 ['Geçerli seçim2·C(4,2)·C(4,3)=2×6×4=48 tanedir.','Olasılık48/56=6/7 bulunur. Doğru seçenek D’dir;soruların hepsinin doğru yapılması rastgele seçimin bölüm koşulunu değiştirmez.'],
 'Yalnız toplam beş doğruyu kontrol etmek geçmek için bölüm başına en aziki koşulunu atlar;örneğin dört sözel bir sayısal yeterli değildir.',
 'Hipergeometrik dağılım','Sabit büyüklükte alt kümede tür sayıları kombinasyon çarpımıyla bulunur;çekilişler bağımsız değildir.',
 'Dörder soruluk iki bölümden beş soru seçiliyor. Tamiki sözel seçme sayısı kaçtır?',['12','16','20','24','48'],3,'Dört sözelden iki,dört sayısaldan üç seçilir:C(4,2)C(4,3)=6×4=24.','D');
 add(134,'Çift çarpım koşulunda çift toplam','Koşullu olasılık','AYT-mat',26,
 'Çarpımın çift olduğu bilgisiyle örnek uzayı daraltıp toplamın çift olmasının artık yalnız iki çift rakamla gerçekleştiğini ölçer.',
 ['1–7 içinde dört tek,üç çift rakam vardır.','Çarpımı çift çiftler toplam C(7,2)−C(4,2)=21−6=15 tanedir;iki tek seçim koşul dışında kalır.'],
 ['Toplam çift için aynı parite gerekir;iki tek zaten dışlandığından iki çift seçilir.','Uygun C(3,2)=3 çift vardır. Koşullu olasılık3/15=1/5,cevap D’dir;payda bütün21 seçim değildir.'],
 'Toplamın çift olduğu bütün çiftleri saymak çarpımın çift olduğu bilgisini kullanmamaktır;iki tek rakam toplamı çift olsa da yasak örneklerdir.',
 'Parite tablosu','Çarpım ve toplamın tek–çift kuralları birlikte yorumlanınca uygun sınıf tek bir tür çiftine iner.',
 'Üç çift,dört tek arasından iki farklı rakam seçiliyor. İkisinin çift olma olasılığı nedir?',['1/7','1/5','2/7','3/7','1/2'],0,'Koşulsuz seçimde payda C(7,2)=21,pay C(3,2)=3’tür;olasılık1/7 olur.','D');
 add(135,'Kapak–tencere eşleşmelerini sayma','Basit olasılık','TYT-mat',80,
 'Kapak seçiminin üç boy arasında,tencere seçiminin ise altı ayrı nesne arasında yapıldığını ayırarak uygun eşleşmeleri saymayı ölçer.',
 ['Üç farklı kapak ve altı tencere toplam18 eş olasılıklı kapak–tencere çifti verir.','Büyük kapak altısına,orta kapak iki orta veüç küçük toplam beşine,küçük kapak üç küçüğe uyar.'],
 ['Uygun eşleşmeleri6+5+3=14 olarak topla.','Olasılık14/18=7/9 bulunur. Doğru seçenek C’dir;tencere boyutlarını eşit olasılıklı üç sınıf gibi almak doğru değildir.'],
 'Bir büyük,iki orta,üç küçük tencere sayısını yok sayıp her boyu1/3 olasılıkla seçmek örnek uzay ağırlıklarını değiştirir.',
 'Ağırlıklı sınıflar','Boy sınıflarının nesne sayıları farklıdır;olasılık her nesneye eşit verildiğinde sınıf olasılıkları sayılarıyla orantılıdır.',
 'Üç kapaktan yalnız büyük olan altı tencerenin hepsine uyuyorsa büyük kapağı seçme olasılığı kaçtır?',['1/6','1/3','1/2','2/3','1'],1,'Rastgele kapak üç ayrı kapaktan biridir. Büyük kapağın seçilmesi1/3 olasılıktadır;tencere sayısı bu ilk seçimi değiştirmez.','C');
 add(136,'Farklı çeklerde iki kişinin yeterli tutarı','Olasılık','TYT-mat',80,
 'Çeklerin geri konmadan farklı iki kişiye verildiğini dikkate alıp500 ve300 TL eşiklerini sıralı seçimlerle saymayı ölçer.',
 ['Yasemin ve Zehra farklı olduğundan dört çekten sıralı iki seçim4×3=12 tanedir.','Zehra500 TL için600 veya800 almalıdır;Yasemin300 TL için400,600,800’den alabilir.'],
 ['Zehra için iki uygun çek seçildiğinde Yasemin’e kalan uygun çek sayısı ikidir.','Toplam2×2=4 uygun dağıtım vardır.4/12=1/3,cevap B’dir;aynı600 veya800 iki kıza birden verilemez.'],
 'Yasemin’in3/4,Zehra’nın1/2 şansını bağımsızmış gibi çarpmak aynı çekin iki kez seçilebildiğini varsayar;çekler birer tanedir.',
 'Sıralı örnek uzay','Hangi çekin kime verildiği sonucu değiştirir;çek çiftinin seçilmesi kadar kişilere dağıtımı da sayılır.',
 '200,400,600,800 TL çeklerinden Zehra’ya500 TL’yi karşılayacak çek kaç biçimde seçilir?',['1','2','3','4','6'],1,'Yalnız600 ve800 TL çekleri500 TL’lik elbiseyi tamamen karşılar;iki seçenek vardır.','B');
 add(137,'Otobüs saatine göre toplam olasılık','Olasılık','AYT-mat',28,
 'Durağa varış sürelerini saniye ölçeğinde otobüsün120 ve180 saniyelik gelişleriyle karşılaştırıp iki ayrık geliş durumunu toplamayı ölçer.',
 ['09.02 gelişinde yalnız100 saniyede varan Duru yetişir;olasılığı1/2’dir.','09.03 gelişinde100 veya150 saniye süreleri yeterlidir;toplam1/2+3/10=4/5’tir.'],
 ['İki geliş durumunu olasılıklarıyla ağırlıklandır:7/10·1/2+3/10·4/5.','35/100+24/100=59/100 bulunur. Doğru seçenek B’dir;250 saniyelik varış iki otobüs saatini de kaçırır.'],
 '150 saniyeyi09.02’den önce sanmak dakika–saniye dönüşümünü atlar;iki dakika120 saniyedir.',
 'Toplam olasılık','Birleşik olay,otobüsün hangi saatte geldiği ayrımına göre koşullu yetişme olasılıklarının ağırlıklı toplamıdır.',
 'Otobüs kesin180 saniyede geliyorsa aynı süre dağılımında Duru’nun yetişme olasılığı nedir?',['1/2','3/5','7/10','4/5','1'],3,'100 ve150 saniyelik varışlar yetişir. Olasılık1/2+3/10=4/5’tir.','B');
 add(138,'İki aşamalı otopark seçiminin eşleşmesi','Olasılık','AYT-mat',28,
 'Önce kapı,sonra o kapıdaki otopark seçildiğinden beş otoparkın eş olasılıklı olmadığını ve arama seçiminin aynı dağılımla tekrarlandığını ölçer.',
 ['İlk kapıdaki iki otoparkın her birine olasılık1/2·1/2=1/4 düşer.','İkinci kapıdaki üç otoparkın her birine1/2·1/3=1/6 düşer;arama da aynı dağılımdadır.'],
 ['Aynı otoparkı seçme olasılığı iki ilk kapı otoparkı için2(1/4)²’dir.','Diğer üçü için3(1/6)² eklenir.1/8+1/12=5/24,cevap B’dir;beş seçenek doğrudan1/5 değildir.'],
 'Otoparkları eşit olasılıkla beşli seçim saymak kapının önce eşit şansla seçildiğini yok sayar;iki aşamanın olasılıkları çarpılır.',
 'Çakışma olasılığı','Aynı dağılımdan bağımsız iki seçimde tam eşleşme olasılığı,paylaşılan sonuçların olasılık karelerinin toplamıdır.',
 'İki park yerinin seçilme olasılıkları1/3 ve2/3 ise bağımsız ikinci aramada aynı yere gelme şansı nedir?',['1/3','4/9','1/2','5/9','2/3'],3,'Eşleşme iki ayrık durumdur:(1/3)²+(2/3)²=1/9+4/9=5/9.','B');
 add(139,'Birim yarıçapla iki dik üçgen','Trigonometrik oranlar','TYT-mat',134,
 'Şekildeki OC=OA=1 yarıçaplarını kullanarak iç ve dış üçgenlerin kenarlarını sinüs,kosinüs,tanjant ve sekantla ifade etmeyi ölçer.',
 ['OD=cos x,CD=sin x;OA=1 olduğundan AB=tan x,OB=sec x olur.','BC=OB−OC=sec x−1 ve DA=OA−OD=1−cos x’tir.'],
 ['Oranı(tan x+sec x−1)/(sin x+1−cos x) biçiminde kur.','Payı cos x paydasında yazınca aynı sin x+1−cos x çarpanı sadeleşir. Sonuç1/cos x=sec x,cevap E’dir.'],
 'BC’yi doğrudan sec x almak OC=1 parçasını unutur;istenen tüm hipotenüs OB değil,dışta kalan CB’dir.',
 'Benzer dik üçgenler','İki üçgen aynı x açısını paylaşır;birinde hipotenüs,diğerinde komşu kenar1 olduğundan farklı oranlar doğal olarak ortaya çıkar.',
 'OA=1 ve OAB dik üçgeninde O açısı x ise OB kaçtır?',['sin x','cos x','tan x','sec x','csc x'],3,'cos x=OA/OB=1/OB olduğundan OB=1/cos x=sec x bulunur.','E');
 add(140,'45–90 derece aralığında sıralama','Trigonometrik sıralama','AYT-mat',33,
 'a aralığını üçle çarparak3a’nın birinci bölgede45° ile90° arasında olduğunu bulup sinüs,kosinüs ve tanjantı sıralamayı ölçer.',
 ['π/12<a<π/6 ise π/4<3a<π/2 olur.','Bu aralıkta0<cos(3a)<sin(3a)<1 ve tan(3a)>1’dir.'],
 ['y=cos(3a) en küçük,x=sin(3a) ondan büyük olarak belirlenir.','z=tan(3a) birden büyük olduğundan x’ten de büyüktür. Sıra y<x<z,cevap C’dir;uçlardaki eşitlikler açık aralık nedeniyle yoktur.'],
 'a’nın kendi15–30 derece aralığına göre sıralama yapmak fonksiyonların3a girdisini gözden kaçırır;önce açı aralığı dönüştürülmelidir.',
 'Birim çember','Birinci bölgede45° sonrasında düşey koordinat sinüs,yatay koordinat kosinüsten büyüktür;tanjant bunların oranıdır.',
 'π/4<t<π/2 için hangisi doğrudur?',['sin t<cos t','tan t<1','cos t<sin t<tan t','sin t=cos t','cos t<0'],2,'Bu aralıkta sinüs kosinüsten büyüktür;tan t=sin t/cos t ve0<cos t<1 olduğundan tanjant sinüsten de büyüktür.','C');
 add(141,'Trigonometrik kesirde eşlenik sadeleşme','Trigonometrik özdeşlikler','AYT-mat',33,
 'Sekant ve tanjantı sinüs–kosinüsle yazıp1−sin x çarpanını cos²x=(1−sin x)(1+sin x) özdeşliğiyle sadeleştirmeyi ölçer.',
 ['sec x·tan x=sin x/cos²x olur.','0<x<π/2 koşulu1−sin x ve cos x’in sıfır olmadığını sağlar;payda sadeleştirmesi geçerlidir.'],
 ['Denklemi sin x/(1+sin x)=1/4 biçimine getir.','4sin x=1+sin x ile sin x=1/3 ve csc x=3 bulunur. Doğru seçenek E’dir;istenen sinüsün kendisi değildir.'],
 'sin x=1/3’te durup cevabı ters çevirmemek kosekant tanımını unutmak demektir;csc x=1/sin x’tir.',
 'Çarpanlara ayırma','1−sin²x farkı iki kare olarak ayrılır;cebirdeki eşlenik kalıbı trigonometrik sadeleşmeyi sağlar.',
 'sin x=2/5 ise csc x kaçtır?',['2/5','3/5','5/3','5/2','2'],3,'Kosekant sinüsün çarpmaya göre tersidir.1/(2/5)=5/2 bulunur.','E');
 add(142,'Boyalı alanın bütün alandan farkı','Trigonometrik alan','TYT-mat',137,
 'Ortak BC kenarlı iki dik üçgende farklı açı konumlarını okuyup sarı alanı büyük üçgenden mavi alanı çıkararak bulmayı ölçer.',
 ['BC=1 seçilirse AC=cot x ve ABC alanı cot x/2 olur.','BCD’de C açısı90°−x olduğundan BD=cos x,CD=sin x; mavi alan sin x cos x/2’dir.'],
 ['Bütün alan/mavi alan oranı cot x/(sin x cos x)=csc²x bulunur.','Sarı/mavi oranı bunun bir eksiğidir:csc²x−1=cot²x. Doğru seçenek D’dir.'],
 'Büyük ABC alanının maviye oranını doğrudan seçmek sarının bütün üçgen değil,BCD çıkarıldıktan sonra kalan bölge olduğunu kaçırır.',
 'Ölçek bağımsızlığı','Oran istendiğinde ortak BC’yi1 almak bütün alanları aynı ölçekle değiştirir;sonuç x’e bağlı kalır.',
 'Bütün alan/mavi alan oranı5 ise sarı kalan alanın maviye oranı kaçtır?',['1','2','3','4','5'],3,'Sarı=bütün−mavi olduğundan oran5−1=4’tür. Alan oranında çıkarılan bölgenin payı1 olarak çıkarılır.','D');
 add(143,'Üçgen açı toplamıyla sinüsü dar açıya çevirme','Trigonometrik sıralama','AYT-mat',36,
 'x+y=180°−z bağıntısıyla büyük görünen açı toplamlarını karşıdaki dar açının sinüsüne dönüştürüp sıralamayı ölçer.',
 ['Üçgen iç açıları x+y+z=180°’dir.','sin(180°−t)=sin t ve dar açılarda sinüs artandır;üç açının da dar olması bu sıralamayı sağlar.'],
 ['a=sin z,b=sin y,c=sin x olarak yeniden yaz.','x>y>z olduğundan sin x>sin y>sin z ve a<b<c bulunur. Doğru seçenek A’dır;açı toplamlarını doğrudan artan sinüs bölgesinde sanma.'],
 'x+y en büyük toplam diye a en büyük demek sinüsün90° sonrasında azaldığını unutur;bütünleyene dönüşüm güvenli yoldur.',
 'Bütünler açı','Üçgendeki iki açının toplamı üçüncünün bütünleyenidir;sinüs bu dönüşümde aynı kalır.',
 'Dar açılı üçgende x>z ise sin(180°−x) ve sin z nasıl sıralanır?',['Birinci küçük','Birinci büyük','Eşit','İkisi negatif','Belirlenemez'],1,'Birinci ifade sin x’tir. Dar açılarda sinüs artan olduğundan x>z ile sin x>sin z çıkar.','A');
 add(144,'Tanjant karesine dönüşen çarpım','Trigonometrik özdeşlikler','AYT-mat',33,
 'İki trigonometrik kesri aynı sinüs–kosinüs tabanına getirip(s+c)(s−c) iki kare farkını kullanmayı ölçer.',
 ['(1+tan x)/cot x=sin x(sin x+cos x)/cos²x olur.','Diğer çarpan(sin x−cos x)/sin x olduğundan çarpım(sin²x−cos²x)/cos²x=tan²x−1’dir.'],
 ['tan²x−1=2 ile tan²x=3 bul.','Birinci bölgede tan x=√3,cos x=1/2 ve sin x=√3/2 olur. Doğru seçenek D’dir;negatif dal açı aralığıyla elenir.'],
 '1+tan x’i tan(1+x) gibi yorumlamak toplamayla fonksiyon girdisini karıştırır;cebirsel ortak payda kullanılmalıdır.',
 'İki kare farkı','Birbirinin eşleniği iki toplamın çarpımı,sinüs ve kosinüs karelerine indirgenir;ardından1+tan²=sec² kullanılır.',
 'Birinci bölgede tan²x=3 ise cos x kaçtır?',['1/3','1/2','√2/2','√3/2','2/3'],1,'sec²x=1+3=4 olduğundan sec x=2 ve cos x=1/2’dir.','D');
 add(145,'Dik yarıçap ve alan oranı','Trigonometrik alan','TYT-mat',137,
 'Şekilde α’nın D köşesinde olduğunu ve OA⊥OD bilgisinin sol üçgende O açısını α yaptığını okuyarak alan oranını kurmayı ölçer.',
 ['OD=OB=1;D açısıα olduğundan OC=sin α,CD=cos α olur.','OA⊥OD nedeniyle OAB üçgeninin O açısıα’dır;OB=1 ve AB=tan α’dır.'],
 ['Sol alan tan α/2,sağ alan sin α cos α/2 olarak yaz.','Oran tan α/(sin α cos α)=1/cos²α=sec²α olur. Doğru seçenek E’dir;α’yı ODC’nin O açısı sanma.'],
 'İşaretlenen açıyı O köşesine taşımak sinüsle kosinüsün rollerini değiştirir;çizimde α,D’de OD ileDC arasındadır.',
 'Tamamlayıcı açı','Dik üçgenin iki dar açısı toplam90° olduğu için dik OA–OD doğrultuları ikinci üçgendeki eş açıyı sağlar.',
 'tan α/(sin α cos α) ifadesi nedir?',['tan²α','cot²α','sec²α','csc²α','1'],2,'tan α=sin α/cos α yazılır;sin α sadeleşir ve1/cos²α kalır.','E');
 add(146,'Katlı açıların farklı bölgeleri','Trigonometrik sıralama','AYT-mat',38,
 'a,2a,3a açılarını ayrı aralıklara taşıyıp tanjantın asimptotu geçince işaret değiştirmesini sıralamaya uygulamayı ölçer.',
 ['π/6<a<π/4 için tan a pozitif ve1’den küçüktür.','2a∈(π/3,π/2) olduğundan tan2a>√3;3a∈(π/2,3π/4) olduğundan tan3a negatiftir.'],
 ['Negatif z en küçük,pozitif x,y arasında y büyüktür.','Sıralama z<x<y olur;doğru seçenek D’dir. Açı büyüdükçe tanjantın her yerde artacağı düşüncesi asimptot geçişinde geçerli değildir.'],
 '3a en büyük açı olduğu için z en büyük demek tanjantınπ/2’de tanımsız olup sağında negatif başladığını göz ardı eder.',
 'Bölgesel monotonluk','Tanjant her süreklilik aralığında artar;farklı aralıklar arasında karşılaştırmada önce işaret ve asimptotlar belirlenir.',
 'π/2<t<π için tan t işareti nedir?',['Pozitif','Negatif','Sıfır','Her zaman1','Tanımsız'],1,'İkinci bölgede sinüs pozitif,kosinüs negatiftir. Tanjant bu iki değerin oranı olduğundan negatiftir.','D');
 add(147,'cos·cot işaretini sinüse indirgeme','Trigonometrik işaretler','AYT-mat',38,
 'cos t·cot t=cos²t/sin t özdeşliğiyle iki ayrı işaret tablosu yerine yalnız sinüsün bölgesini izlemeyi ölçer.',
 ['a∈(π/4,π/3) olduğundan2a ikinci,4a üçüncü,6a dördüncü bölgededir.','cos²t pozitif olduğundan ürünün işareti sin t’nin işaretidir;aralıkların içinde kosinüs sıfır değildir.'],
 ['İkinci bölgede sinüs pozitif,üçüncü ve dördüncüde negatiftir.','Bu nedenle x,y,z işaretleri+,−,− olur. Doğru seçenek C’dir;4a ve6a için periyodik bölgeler ayrı değerlendirilir.'],
 'cos ve cot’un işaretlerini bağımsız ezberlerken yanlış çarpmak yerine kareli sadeleşme yapmak daha güvenli bir kontrol sağlar.',
 'Oran özdeşliği','Kotanjantın cos/sin olması kosinüsü kareye dönüştürür;bu yapısal özellik işaret sorusunu tek fonksiyona indirger.',
 'π<t<3π/2 için cos t·cot t işareti nedir?',['Pozitif','Negatif','Sıfır','Belirsiz','Her zaman1'],1,'Ürün cos²t/sin t biçimindedir. Üçüncü bölgede sinüs negatif olduğundan sonuç negatiftir.','C');
 add(148,'İkinci ve dördüncü bölgeyi birlikte izleme','Trigonometrik işaretler','AYT-mat',38,
 'a’nın ikinci bölgesinden2a’nın dördüncü bölgesine geçip üç farklı çarpımda sinüs,tanjant,kosinüs,kotanjant işaretlerini doğru eşleştirmeyi ölçer.',
 ['3π/4<a<π için sin a>0,tan a<0’dır.','3π/2<2a<2π için sin2a<0,cos2a>0,cot2a<0’dır.'],
 ['x=sin2a·tan a iki negatifin çarpımı olduğundan pozitiftir.','y=cos2a·cot2a ve z=sin a·cot2a bir pozitif bir negatif çarptığından negatiftir. İşaretler+,−,−,cevap B’dir.'],
 '2a’yı a ile aynı bölgede kabul etmek açı iki katına çıktığında işaretlerin değiştiğini kaçırır;önce yeni aralık yazılmalıdır.',
 'Açı ölçekleme','Aralığın iki ucunu da ikiyle çarpmak katlı açının bölgesini kesinleştirir;örnek tek açı seçmekten daha genel kanıttır.',
 'a ikinci bölgede ve2a dördüncü bölgedeyse sin2a·tan a işareti nedir?',['Pozitif','Negatif','Sıfır','Tanımsız','Belirsiz'],0,'sin2a ve tan a negatiftir. İki negatifin çarpımı pozitiftir.','B');
 add(149,'Sinüs,tanjant,sekantı ortak paydada sıralama','Trigonometrik sıralama','AYT-mat',33,
 '40° dar açısında sinüsün pozitif ve birden küçük olmasını kullanarak tanjant ve sekantı kosinüs paydasında karşılaştırmayı ölçer.',
 ['0<cos40°<1 olduğundan sin40°<sin40°/cos40°=tan40° olur.','0<sin40°<1 ve aynı pozitif cos40° paydasında tan40°<1/cos40°=sec40°’dir.'],
 ['Önce a<c,sonra c<b ilişkisini kur.','a<c<b sıralaması B seçeneğidir. Sayısal yaklaşık değer bulmak gerekmez;sekant1’den büyükken sinüs1’den küçüktür.'],
 'sec x’i cos x sanmak b’yi küçük gösterir;sekant kosinüsün tersidir ve dar açıda en az1’dir.',
 'Pozitif sayıya bölme','Birden küçük pozitif paydaya bölmek sinüsü büyütür;aynı paydada ise payların sırası korunur.',
 '0<t<π/2 için hangi sıra geçerlidir?',['tan t<sin t<sec t','sin t<tan t<sec t','sec t<tan t<sin t','sin t=tan t','sec t<sin t'],1,'sin t<tan t,çünkü0<cos t<1;tan t<sec t,çünkü sin t<1 ve paydalar aynıdır.','B');
 add(150,'Dikdörtgen köşegeni ve yarım kenar','Trigonometrik geometri','TYT-mat',134,
 'E’ninAD kenarının ortası ve yüksekliğin1 olduğu bilgisini yarıçap simetrisiyle birleştirerek dikdörtgen genişliğini cot x bulmayı ölçer.',
 ['AE=ED=1/2 olduğundan AD=1’dir;O merkezli çemberde aynı yükseklikte C,D noktaları simetriktir,OA=OB olur.','OAE dik üçgeninde tan x=(1/2)/OA,OA=cot x/2’dir.'],
 ['AB=2OA=cot x ve AD=1 olarak kenarları yaz.','Köşegen√(cot²x+1)=csc x bulunur. Doğru seçenek B’dir;OE istenen köşegen değildir.'],
 'OA’yı dikdörtgenin tam genişliği almak AB’nin iki kat olduğunu kaçırır;merkez O alt kenarın orta noktasıdır.',
 'Pisagor özdeşliği','Geometrik köşegen hesabındaki1+cot²x,doğrudan csc²x trigonometrik özdeşliğine dönüşür.',
 'Kenarları1 ve cot x olan dikdörtgenin köşegeni nedir?',['sin x','cos x','tan x','sec x','csc x'],4,'Pisagor ile köşegen karesi1+cot²x=csc²x olur. Dar açıda köşegen pozitif olduğundan csc x alınır.','B');
 add(151,'Üç özel açıyı farklı değişkenlere atama','Özel trigonometrik değerler','AYT-mat',36,
 'π/4,3π/4,5π/4 için sinüs,tanjant,sekant değerlerini ayrı değerlendirip sin x<tan y<sec z zincirini sağlayan tek atamayı bulmayı ölçer.',
 ['Bu açılarda sinüs±√2/2,tanjant±1,sekant±√2 değerlerini alır.','tan y=−1 olursa bütün mümkün sin x değerlerinden küçük kalır;bu yüzden tan y=1 olmalıdır.'],
 ['sec z>1 gerektiğinden z=π/4 seçilir. Kalan açılarda tan y=1 yalnız y=5π/4 ile olur.','x=3π/4 kalır. Sayısal açı sırası z<x<y,cevap D’dir;fonksiyon değer sırasıyla açı sırası aynı şey değildir.'],
 'Verilen sin x<tan y<sec z sırasını doğrudan x<y<z diye yazmak fonksiyonların farklılığını ve bölge işaretlerini yok sayar.',
 'Kısıtlı eşleştirme','En büyük zorunlu değerden başlamak z’yi sabitler;farklı eleman koşulu diğer atamaları belirler.',
 'sec z>1 ve z∈{π/4,3π/4,5π/4} ise z hangisidir?',['π/4','3π/4','5π/4','π','Hiçbiri'],0,'Yalnızπ/4’te kosinüs pozitiftir;sekant√2>1 olur. Diğer ikisinde sekant−√2’dir.','D');
 add(152,'Ortak yükseklikte iki eğim','Doğru ve tanjant','AYT-mat',100,
 'İki doğrunun(b,h) ortak noktasını kullanıp taban uzunluklarını tanjantla ilişkilendirerek a/b oranını çıkarmayı ölçer.',
 ['Orijinden geçen d₁ için h=b tan A’dır.','x eksenini a’da kesen d₂ için h=(b−a)tan B’dir;iki doğru aynı yükseklikte kesişir.'],
 ['b tan A=(b−a)tan B eşitliğini b tan B’ye böl.','tan A·cot B=1−a/b ve a/b=1−tan A·cot B bulunur. Doğru seçenek E’dir.'],
 'İkinci üçgenin tabanını a almak şekilde a’nın kesişimin değil doğrunun x kesişiminin apsisi olduğunu unutur;taban b−a’dır.',
 'Eğim tanımı','Doğrunun yatayla açısının tanjantı yükseklik/yatay uzunluk oranıdır;aynı h iki üçgeni bağlar.',
 'Ortak h için h=b tan A=(b−a)tan B ise(b−a)/b nedir?',['tan A/tan B','tan B/tan A','tan A tan B','cot A cot B','1'],0,'İki eşitlik bölününce(b−a)/b=tan A/tan B bulunur;bu tan A·cot B’dir.','E');
 add(153,'Pergel açıklığı yarıçaptır','Kosinüs teoremi','AYT-mat',39,
 'Çemberin21 cm çapından uçlar arası10,5 cm açıklığı bulup7,5 ve12 cm pergel kollarının arasındaki açıyı kosinüs teoremiyle ölçer.',
 ['Pergelin iki ucu arasındaki mesafe çizilen çemberin yarıçapıdır;çapın yarısı10,5 cm’dir.','Üçgende karşı kenar10,5;komşu kenarlar7,5 ve12 olduğundan cosθ=(7,5²+12²−10,5²)/(2·7,5·12)’dir.'],
 ['Pay56,25+144−110,25=90,payda180 bulunur.','cosθ=1/2 olduğundan pergel açıklık açısı60°’dir. Doğru seçenek C’dir;çap21’i doğrudan üçgen kenarı yapmak mümkün değildir.'],
 'Çapı pergel açıklığı saymak21>7,5+12 olduğu için üçgen eşitsizliğini de bozar;geometrik model yarıçapla kurulmalıdır.',
 'Araçtan üçgen modeli','Pergelin menteşesiyle iki ucu üçgen oluşturur;araç açıklığı ile çizilen dairenin yarıçapı aynı uzunluktur.',
 'Kenarları7,5 ve12,aralarındaki açısı60° olan üçgende üçüncü kenar kaçtır?',['7,5','9','10,5','12','15'],2,'Kosinüs teoremiyle c²=56,25+144−180·1/2=110,25 olur;c=10,5’tir.','C');
 add(154,'Kenar eşitliğinden geniş açı tanjantı','Kosinüs teoremi','AYT-mat',39,
 '2a²=2b²+2c²+3bc eşitliğini kosinüs teoremiyle karşılaştırıp negatif kosinüsten açının geniş olduğunu belirlemeyi ölçer.',
 ['a²=b²+c²+(3/2)bc ve kosinüs teoremi a²=b²+c²−2bc cos x’tir.','Karşılaştırmadan cos x=−3/4 çıkar;iç açı0–π arasında olduğundan sin x pozitiftir.'],
 ['sin x=√(1−9/16)=√7/4 bul.','tan x=(√7/4)/(−3/4)=−√7/3 olur. Doğru seçenek E’dir;sinüsün negatif dalı üçgen açısı için alınmaz.'],
 'Kenar eşitliğindeki+3bc’yi pozitif kosinüs sanmak kosinüs teoremindeki eksi işaretini unutmak demektir.',
 'Bölge ve karekök','Kosinüs değeri negatif olduğunda iç açı ikinci bölgededir;sinüs pozitif,tanjant negatif olur.',
 'Üçgen açısı x için cos x=−4/5 ise tan x nedir?',['−3/4','−4/3','3/4','4/3','5/4'],0,'İç açı nedeniyle sin x=3/5 pozitiftir. Tanjant(3/5)/(−4/5)=−3/4 olur.','E');
 add(155,'Değişen kenarlarda60 derecelik üçgen','Kosinüs teoremi','AYT-mat',39,
 'İlk dönüşümün eşkenarlığından a=b+3,ikinci dönüşümün30–60–90 oranından a+2=2b ilişkilerini kurmayı ölçer.',
 ['b üç artırılınca a ile eşit olduğundan a=b+3’tür.','İkinci üçgen dik ve içerilen açı60°’dir;a+2 büyük kenar olduğundan hipotenüs,b ise60°’ye komşu kısa dik kenardır.'],
 ['a+2=2b ile b+5=2b,b=5,a=8 bul.','Başlangıçta c²=a²+b²−2ab cos60°=64+25−40=49 olur;c=7,cevap D’dir.'],
 'İkinci üçgende c’yi hipotenüs seçmek60°’nin karşısındaki kenarın hipotenüs değil uzun dik kenar olduğunu kaçırır;hipotenüs a+2’dir.',
 'Özel üçgen ve genel teorem','Dönüşmüş üçgen oranı bilinmeyen kenarları bulur;başlangıç üçgeninin c’si ise ayrı kosinüs hesabıyla belirlenir.',
 'Kenarları5 ve8,aralarındaki açı60° olan üçgende karşı kenar kaçtır?',['5','6','7','8','9'],2,'c²=25+64−2·5·8·1/2=49 olduğundan c=7’dir.','D');
 add(156,'Tamamlayıcı ve iki kat açı zinciri','Trigonometrik özdeşlikler','AYT-mat',47,
 'cot34° ve sin56°’yi tamamlayıcı bağıntıyla sadeleştirip sin44°’ün iki kat açı açılımından hedef ifadeye ulaşmayı ölçer.',
 ['sin56°=cos34° ve cot34°=cos34°/sin34°’tür.','sin44°=2sin22°cos22°,ayrıca cos22°=sin68°=2sin34°cos34° olur.'],
 ['Başlangıç oranında cos34° ve sin22° çarpanlarını sadeleştir;2cos22°/sin34° kalır.','İkinci iki kat bağıntısıyla bu4cos34° olur. Doğru seçenek D’dir;açılar birbirinin tamamlayıcısı olarak seçilmiştir. Sadeleşen dar açı sinüsleri sıfır olmadığı için bölmeler geçerlidir.'],
 'sin44°’ü2sin22° biçiminde açmak eksik cos22° çarpanı nedeniyle yanlış sadeleşme verir.',
 'İki aşamalı açı dönüşümü','44=2·22 ve68=2·34 ilişkileri,90° tamamlayıcı dönüşümüyle birbirine bağlanır.',
 'sin68°/sin34° ifadesi nedir?',['cos34°','2cos34°','2sin34°','tan34°','1'],1,'sin68°=2sin34°cos34° olduğundan ortak sin34° sadeleşir ve2cos34° kalır.','D');
 add(157,'Payda sinüs karesini üretme','Trigonometrik özdeşlikler','AYT-mat',47,
 '2tan x−sin2x farkını ortak paydada yazıp1−cos²x=sin²x ile paydadaki sin²x’i sadeleştirmeyi ölçer.',
 ['tan x=sin x/cos x,sin2x=2sin x cos x’tir.','Fark2sin x(1−cos²x)/cos x=2sin³x/cos x olur.'],
 ['Bu ifadeyi verilen sin²x paydasına böl.','Sonuç2sin x/cos x=2tan x’tir;doğru seçenek A’dır. Sadeleşme yalnız özgün ifadenin tanımlı olduğu sin x≠0,cos x≠0 noktalarında kullanılır.'],
 '2tan x−sin2x’i sin2x ile tan2x farkı gibi görmek iki kat açının farklı işlevlerini karıştırır.',
 'Pisagor özdeşliği','1−cos²x yerine sin²x yazmak payda ile ortak çarpanı görünür kılar;temel özdeşlik işlem kısaltır.',
 '(1−cos²x)/sin²x,tanımlı olduğu yerde kaçtır?',['0','1','sin x','cos x','tan x'],1,'1−cos²x=sin²x olduğundan oran1’dir;sin x sıfırsa başlangıç kesri tanımsızdır.','A');
 add(158,'80 dereceyi20 dereceye indirme','Trigonometrik özdeşlikler','AYT-mat',47,
 'Kareli ifadeyi çift açıya çevirip cos160°=−cos20° ve cos50°=sin40° ilişkileriyle sadeleştirmeyi ölçer.',
 ['cos²80°+5sin²80°−3=4sin²80°−2=−2cos160°’dir.','cos160°=−cos20°,cos50°=sin40°=2sin20°cos20° olur. Verilen50° dar açı olduğundan payda sıfır değildir; oran pozitif ve sonlu bir sayı olmalıdır.'],
 ['Pay2cos20°’ye,payda2sin20°cos20°’ye dönüşür.','Oran1/sin20°=csc20° bulunur. Doğru seçenek D’dir;160° dönüşümündeki eksi işareti sonucu pozitif yapar.'],
 'cos160°’yi cos20° olarak almak ikinci bölgedeki kosinüs işaretini unutur;başlangıç oranın pozitifliği de kontrol sağlar.',
 'Açı sadeleştirme','80°,160°,50°,40° farklı görünse de tamamlayıcı ve iki kat ilişkileriyle tek20° açısına iner.',
 '2cos20°/sin40° ifadesinin eşiti nedir?',['sec20°','csc20°','tan20°','2sin20°','cos40°'],1,'sin40°=2sin20°cos20° olduğundan sonuç1/sin20°’dir.','D');
 add(159,'Yeni fonksiyonları kiriş uzunluğundan çözme','Birim çember ve yarım açı','AYT-mat',47,
 'Tanımlanan kas ve sas sembollerini standart fonksiyon sanmadan R=(cosθ,sinθ) koordinatıyla iki kiriş uzunluğunu hesaplamayı ölçer.',
 ['kas²θ=RS²=(cosθ−1)²+sin²θ=2−2cosθ’dir.','sas²θ=RP²=cos²θ+(sinθ−1)²=2−2sinθ olur.'],
 ['Oran(2−2cosθ)/(2−(2−2sinθ))=(1−cosθ)/sinθ biçimine iner.','Yarım açı özdeşliğiyle tan(θ/2) elde edilir. Doğru seçenek D’dir;sembol adları yalnız verilen uzunluk tanımlarıyla anlam kazanır.'],
 'kas ile sas’ı sırasıyla kosinüs ve sinüs kabul etmek sorunun yeni tanımını yok sayar;her biri çemberde bir kiriş uzunluğudur.',
 'Uzaklık formülü','Koordinatlar arasındaki uzaklığın karesi temel sin²+cos²=1 özdeşliğiyle sadeleşir ve yarım açıya bağlanır.',
 '(1−cosθ)/sinθ,tanımlı olduğu yerde nedir?',['tanθ','cotθ','tan(θ/2)','cot(θ/2)','secθ'],2,'1−cosθ=2sin²(θ/2),sinθ=2sin(θ/2)cos(θ/2) yazılınca tan(θ/2) kalır.','D');
 add(160,'İki ışının eğiminden açı farkı','Tanjant fark formülü','AYT-mat',46,
 'y=1/x üzerindeki K,L koordinatlarını okuyup OK ve OL eğimlerini açılarının tanjantı olarak kullanmayı ölçer.',
 ['K=(1,1),L=(2,1/2)’dir;OK eğimi1,OL eğimi1/4’tür.','Aradaki α açısı ışınların eğim açılarının farkıdır;tanjant farkı(t₁−t₂)/(1+t₁t₂) kullanılır.'],
 ['tanα=(1−1/4)/(1+1/4) eşitliğini kur.','(3/4)/(5/4)=3/5 bulunur. Doğru seçenek E’dir;L’nin ordinatı1/2 olsa da ışın eğimi bunun apsise bölümü1/4’tür.'],
 'L’nin y değerini doğrudan tanjant almak x=2 apsisini ihmal eder;doğru eğimi y/x olarak hesaplanır.',
 'Analitik ve trigonometrik bağ','Orijinden çıkan doğru eğimleri açıların tanjantını verir;grafik koordinat bilgisi fark formülüne aktarılır.',
 'İki ışının eğimleri1 ve1/2 ise aralarındaki dar açının tanjantı kaçtır?',['1/5','1/4','1/3','1/2','2/3'],2,'Fark formülü(1−1/2)/(1+1/2)=(1/2)/(3/2)=1/3 verir.','E');
 add(161,'Sekant–tanjant farkından çift açı','Trigonometrik özdeşlikler','AYT-mat',47,
 'sec²x−tan²x=1 özdeşliğini önce uygulayıp kalan1−cos2x ifadesini sinüs karesine dönüştürmeyi ölçer.',
 ['Paydaki ilk iki terim sec²x−tan²x=1 verir.','1−cos2x=2sin²x ve tan x=sin x/cos x bağıntıları kullanılır.'],
 ['İfade2sin²x/(sin x/cos x)=2sin x cos x olur.','Sonuç sin2x’tir;doğru seçenek A’dır. Bütün dönüşümler özgün ifadenin tanımlı olduğu tan x≠0 ve cos x≠0 noktalarında geçerlidir.'],
 'sec²x−tan²x’i cos²x−sin²x sanmak ters fonksiyon adlarını karıştırarak yanlış çift açıya götürür.',
 'Pisagor özdeşliği','1+tan²x=sec²x,temel sin²+cos²=1 bağıntısının cos²x’e bölünmüş biçimidir;aynı temel ilişki iki kez kullanılır.',
 '(1−cos2x)/tan x ifadesi,tanımlı olduğu yerde nedir?',['sin2x','cos2x','tan2x','2','1'],0,'Pay2sin²x olur. Tanjanta bölmek cos x/sin x ile çarpmaktır;sonuç2sin x cos x=sin2x’tir.','A');
 add(162,'Eş alanlardan yarım açının kosinüsü','Sinüslü alan ve kosinüs teoremi','AYT-mat',39,
 'İki üçgenin½ab sinθ alanlarını eşitleyip mavi açının2θ olmasından cosθ’yi bulmayı ve kırmızı çevresini hesaplamayı ölçer.',
 ['Mavi alan108sin2θ,kırmızı alan36sinθ’dir.','Üçgen açısı0<θ<π olduğundan sinθ≠0;sin2θ=2sinθ cosθ ile sadeleştirme yapılabilir.'],
 ['216cosθ=36’dan cosθ=1/6 bul.','Kırmızı üçüncü kenar²=8²+9²−2·8·9/6=121;kenar11’dir. Çevre8+9+11=28,cevap B’dir.'],
 'Alanlar eşit diye12·18=8·9 demek açının alanı değiştirdiğini unutur;sinüs çarpanı zorunludur.',
 'Alan ve kenar bağı','Sinüslü alan bilinmeyen açının kosinüsünü iki kat açıyla belirler;ardından kosinüs teoremi eksik kenarı tamamlar.',
 'Kenarları8,9 ve aralarındaki açının kosinüsü1/6 olan üçgenin üçüncü kenarı kaçtır?',['9','10','11','12','13'],2,'Kosinüs teoremiyle c²=64+81−144/6=121 bulunur;c=11’dir.','B');
 add(163,'Kotanjantı açıp eşlenik payda kurma','Trigonometrik özdeşlikler','AYT-mat',47,
 '1/(1+cot x) ifadesini sin x/(sin x+cos x) yapıp iki kesrin farkında çift açı kalıbı oluşturmayı ölçer.',
 ['1/(1+cot x)=sin x/(sin x+cos x)’tir.','Paydaların çarpımı(sin x+cos x)(sin x−cos x)=sin²x−cos²x olur.'],
 ['Ortak paydada pay−2sin x cos x, payda−cos2x çıkar.','İki eksi sadeleşir;sin2x/cos2x=tan2x bulunur. Doğru seçenek C’dir;özgün paydaların sıfır olmadığı noktalar korunur.'],
 'Kesirlerin farkında yalnız payları çıkarmak farklı paydaları yok sayar;özellikle iki eksi işareti sonuçta birbirini giderir.',
 'İki kare farkı','Toplam ve fark eşlenikleri,sin²−cos² üzerinden cos2x’i üretir;paydaki çarpım sin2x’e dönüşür.',
 '−2sin x cos x/(sin²x−cos²x) nedir?',['−tan2x','tan2x','cot2x','sec2x','1'],1,'Pay−sin2x,payda−cos2x’tir. Oran tan2x olur.','C');
 add(164,'Paralelkenar alanında iki kat açı','Trigonometrik alan','TYT-mat',137,
 'İlk paralelkenarın alanından sin x’i çıkarıp ikinci şeklin2x iç açısı olmasıyla x’in dar olduğunu belirleyerek cos x’in pozitif dalını seçmeyi ölçer.',
 ['İlk alan4·8sin x=24 olduğundan sin x=3/4’tür.','İkinci paralelkenarın iç açısı2x,0–180° arasındadır;bu nedenle0<x<90° ve cos x=√7/4 olur.'],
 ['sin2x=2·3/4·√7/4=3√7/8 hesapla.','İkinci alan4·6·3√7/8=9√7 bulunur. Doğru seçenek D’dir;alan kenar çarpımına açı sinüsünü de içerir.'],
 'Sadece kenar çarpımlarını24/32 oranlamak iki şeklin açıları farklı olduğu için geçersizdir;sin x yerine sin2x kullanılır.',
 'Geometrik aralık koşulu','Şeklin2x açısı olması,karekök alırken gereken cos x işaretini cebirsel veriye ek olarak sağlar.',
 'sin x=3/4 ve x dar ise sin2x kaçtır?',['3√7/16','√7/4','3√7/8','3/8','7/8'],2,'cos x=√7/4’tür.2sin x cos x=2·3/4·√7/4=3√7/8 bulunur.','D');
 add(165,'Dikdörtgen ve ikizkenar üçgende ortak yükseklik','Trigonometrik alan','TYT-mat',137,
 'Çember yarıçapını r,ortak yatay doğrunun yüksekliğini h alıp dikdörtgen ve OEF üçgeninin aynı yüksekliğini sadeleştirmeyi ölçer.',
 ['Dikdörtgen genişliği çap2r,alanı2rh’dir.','OEF ikizkenar üçgeninde tepe açısı x,kiriş EF=2r sin(x/2) ve alan r h sin(x/2) olur.'],
 ['Oranı2rh/[rh sin(x/2)] olarak yaz.','Sonuç2csc(x/2)’dir;doğru seçenek C’dir. Dikdörtgenin genişliği EF değil,AD çapıdır;E,F üst kenarın içindedir.'],
 'Dikdörtgenin üst kenarınıEF kirişine eşit almak C,F,E,B doğrusu üzerindeki dış parçaları yok sayar;tam üst kenar CB çap uzunluğundadır.',
 'Ortak taban doğrusu','Alan oranında h ortak olduğundan yükseklik veya yarıçapın sayısal değerini bulmak gerekmez;esas fark taban uzunluğudur.',
 'Tepe açısı60°,eş kenarlarır olan ikizkenar üçgenin tabanı kaçtır?',['r/2','r','√2r','√3r','2r'],1,'Taban2r sin30°=r’dir. Tepe açıortayı iki eş dik üçgen oluşturur.','C');
 add(166,'Toplam–fark açılımlarında ortak çarpan','Trigonometrik toplam fark','AYT-mat',45,
 'cos(2x+y) ve sin(2x−y) açılımlarını aynı cos2x+sin2x çarpanı etrafında gruplamayı ölçer.',
 ['cos(2x+y)=cos2x cos y−sin2x sin y’dir.','sin(2x−y)=sin2x cos y−cos2x sin y olur;iki sin y terimi de negatiftir.'],
 ['Payı(cos2x+sin2x)(cos y−sin y) biçiminde çarpanlara ayır.','Verilen paydayla ortak çarpan sadeleşince cos y−sin y kalır. Doğru seçenek A’dır;paydanın sıfır olduğu noktalar başlangıçta tanımsızdır.'],
 'sin(2x−y) açılımında ikinci terimi pozitif almak cos y+sin y çeldiricisini üretir;fark açısının işareti korunmalıdır.',
 'Cebirsel gruplama','Trigonometrik açılım sonrası sorun ortak çarpan parantezine alma işlemidir;tam sayısal açı bilgisi gerekmez.',
 '(u+v)cos y−(u+v)sin y ifadesinde ortak çarpan dışında ne kalır?',['cos y+sin y','cos y−sin y','sin y−cos y','cos2y','1'],1,'Her iki terimdeki u+v ayrılınca kalan cos y−sin y olur;çıkarma işareti değişmez.','A');
 add(167,'Dördüncü açıdan yarım açı oranı','Trigonometrik özdeşlikler','AYT-mat',47,
 '1−cos4x ve sin4x ifadelerini2x cinsinden yazıp sin2x/(1+cos2x) oranının tan x olduğunu ölçer.',
 ['1−cos4x=2sin²2x ve sin4x=2sin2x cos2x’tir.','Payda2sin2x(cos2x+1) biçiminde ortak çarpan içerir.'],
 ['Ortak2sin2x sadeleşince sin2x/(1+cos2x) kalır.','sin2x=2sin x cos x,1+cos2x=2cos²x ile sonuç tan x olur. Doğru seçenek B’dir;başlangıç paydasının sıfırları hariç tutulur.'],
 'Paydadaki+2sin2x’i sin6x diye toplamak sinüsün toplama üzerinde doğrusal olmadığını unutur.',
 'Yarım açı özdeşliği','sin2x/(1+cos2x) tan x’in standart gösterimidir;iki kat açı dönüşümü oranın açısını yarıya indirir.',
 'sin2x/(1+cos2x),tanımlı olduğu yerde nedir?',['sin x','tan x','cot x','sec x','csc x'],1,'Üst ve altı iki kat açıyla açınca2sin x cos x/(2cos²x)=tan x olur.','B');
 add(168,'Homojen eşitlikte kotanjant oranı','Trigonometrik denklemler','AYT-mat',50,
 'Sabit9’u9(sin²x+cos²x) olarak yazıp sin2x’i açarak ortak cos x üzerinden kotanjantı ayırmayı ölçer.',
 ['2cos²x+9sin²x+4sin x cos x=9sin²x+9cos²x olur.','Birinci bölgede sin x ve cos x sıfır değildir;4sin x cos x=7cos²x eşitliğinde bölme yapılabilir.'],
 ['cos x’i sadeleştirerek4sin x=7cos x bul.','cot x=cos x/sin x=4/7’dir. Doğru seçenek A’dır;istenen tanjant olsaydı ters oran7/4 olurdu.'],
 'sin2x’in başındaki2’yi unutmak4sin x cos x yerine2sin x cos x yazdırır ve oranı iki kat bozar.',
 'Homojenleştirme','Sabit terimi sin²+cos² ile değiştirmek bütün terimleri ikinci derece yapar;ardından oranla çözüm mümkün olur.',
 '4sin x=7cos x ve x dar ise tan x kaçtır?',['4/7','7/4','3/7','7/3','1'],1,'Eşitliği4cos x’e bölünce tan x=7/4 elde edilir. Kotanjant bu oranın tersidir.','A');
 add(169,'Dördüncü kuvvetlerde tam kare','Trigonometrik özdeşlikler','AYT-mat',47,
 'sin²2x terimini4sin²x cos²x olarak açıp payı2(sin²x+cos²x)² yapmayı ölçer.',
 ['Pay2cos⁴x+4sin²x cos²x+2sin⁴x=2’dir.','Payda2(cos⁴x−sin⁴x)=2(cos²x−sin²x)(cos²x+sin²x)=2cos2x’tir. Bu nedenle sonuç yalnız cos2x sıfır olmayan girdilerde tanımlıdır; özgün kesrin paydası da aynı koşulu gerektirir.'],
 ['İki özdeşliği kullanarak uzun kesri2/(2cos2x) biçimine indir.','Sonuç sec2x olur;doğru seçenek C’dir. Payda sıfır olduğunda özgün ifade de tanımsız olduğundan sadeleşme bu kısıtı korur.'],
 'cos⁴+sin⁴=1 yazmak çapraz2sin²cos² terimini ihmal eder;burada sin²2x o eksik terimi tam kareye tamamlar.',
 'Tam kare özdeşliği','u²+2uv+v²=(u+v)² kalıbında u=cos²x,v=sin²x seçilir;trigonometrik toplam1’e dönüşür.',
 'cos⁴x+2sin²x cos²x+sin⁴x kaçtır?',['0','1','2','cos2x','sin2x'],1,'İfade(cos²x+sin²x)²=1²=1’dir.','C');
 add(170,'Çarpımlardan toplam açının kosinüsü','Toplam açı formülleri','AYT-mat',45,
 'İstenen sin x cos y+cos x sin y’nin sin(x+y) olduğunu görüp verilen iki çarpım farkından cos(x+y)’yi hesaplamayı ölçer.',
 ['cos(x+y)=cos x cos y−sin x sin y=3/14−5/7=−1/2’dir.','x,y dar olduğundan0<x+y<π;bu aralıkta sin(x+y)>0 olur.'],
 ['cos(x+y)=−1/2 ile sin²(x+y)=3/4 bul.','Pozitif dal sin(x+y)=√3/2 seçilir. Doğru seçenek B’dir;x iley’yi ayrı ayrı bulmaya gerek yoktur.'],
 'Verilen iki çarpımı toplayarak isteneni bulduğunu sanmak cos(x−y) ile sin(x+y) formüllerini karıştırır;önce bilinen farktan başlanır.',
 'Açı aralığı ve işaret','Sinüsün karekök dalını tek tek x,y değil,toplamlarının0–π aralığı belirler.',
 '0<t<π ve cos t=−1/2 ise sin t kaçtır?',['−√3/2','−1/2','1/2','√2/2','√3/2'],4,'Bu aralıkta sinüs pozitiftir. sin²t=1−1/4=3/4 olduğundan sin t=√3/2’dir.','B');
 add(171,'Sabit bant uzunluğunda yükseklik oranı','İki kat açı ve dik üçgen','AYT-mat',47,
 'Açı iki katına çıktığında sabit hipotenüslü bant yüksekliğinin sin2x/sin x oranını kullanıp yatay120 cm ile uzunluğu bulmayı ölçer.',
 ['Bant uzunluğu L için ilk yükseklik Lsin x,ikinci Lsin2x’tir.','Yükseklik oranı80/41=sin2x/sin x=2cos x verir;cos x=40/41’dir.'],
 ['İlk şekilde yatay mesafe Lcos x=120 cm olur.','L=120·41/40=123 cm bulunur. Doğru seçenek A’dır;şekilde41h ve80h yükseklik etiketleri oranı temsil eder.'],
 '120 cm’yi bant uzunluğu sanmak yatay izdüşümle eğimli hipotenüsü karıştırır;bant ilk konumda bile120’den uzundur.',
 'Sabit hipotenüs','İki konumda aynı L sadeleşir;yükseklik oranı doğrudan ilk açının kosinüsünü verir.',
 'Sabit uzunluklu çubukta sin2x/sin x=3/2 ise cos x kaçtır?',['1/4','1/2','3/4','√3/2','1'],2,'sin2x=2sin x cos x olduğundan oran2cos x’tir.2cos x=3/2,cos x=3/4 olur.','A');
 add(172,'Çift açı denkleminde iki çözüm','Trigonometrik denklemler','AYT-mat',49,
 'İki kesri çapraz çarpıp sin2x=−cos2x’e dönüştürerek0<x<π aralığında iki katlı açının tam periyodunu taramayı ölçer.',
 ['2sin x cos x=(sin x−cos x)(sin x+cos x)=sin²x−cos²x olur.','Bu eşitlik sin2x=−cos2x,tan2x=−1 verir;2x∈(0,2π)’dir.'],
 ['2x=3π/4 veya7π/4, dolayısıyla x=3π/8 veya7π/8 bulunur.','İki çözümde özgün sin x+cos x paydası sıfır değildir. Toplam5π/4,cevap B’dir.'],
 'tan2x=−1 için yalnız ikinci bölge çözümünü almak2x’in0–2π aralığındaki dördüncü bölge çözümünü kaybeder.',
 'Aralık dönüştürme','Denklem2x ile çözülünce aralık da iki katına çıkarılır;sonunda bulunan açılar ikiye bölünür.',
 '0<t<2π ve tan t=−1 ise çözümler toplamı kaçtır?',['π','3π/2','2π','5π/2','3π'],3,'t=3π/4 ve7π/4’tür. Toplam10π/4=5π/2 bulunur.','B');
 add(173,'Mutlak sinüsün üç bölgedeki kökleri','Trigonometrik denklemler','AYT-mat',49,
 'cos50°=sin40° dönüşümünden sonra mutlak değerin hem pozitif hem negatif sinüs çözümlerini0–270° aralığında saymayı ölçer.',
 ['|sin x|=sin40° için sin x=sin40° veya sin x=−sin40° olur.','0≤x≤270° aralığında çözümler40°,140°,220°’dir;320° aralık dışındadır.'],
 ['Üç çözümü toplayıp400° bul.','Radyana dönüşüm400π/180=20π/9 verir. Doğru seçenek E’dir;negatif sinüs dalındaki220° unutulmamalıdır.'],
 'Mutlak değeri kaldırıp yalnız sin x=cos50° çözmek üçüncü bölgedeki kökü eksiltir;mutlak değer işaret farkını ortadan kaldırır.',
 'Derece–radyan dönüşümü','Veri dereceyle,cevaplar radyanla yazılmıştır;toplamı en sondaπ/180 ile çarpmak işlem yükünü azaltır.',
 '0≤x≤π aralığında|sin x|=sin40° çözümleri toplamı kaçtır?',['π/2','π','3π/2','2π','20π/9'],1,'Bu aralıkta sinüs zaten pozitiftir;40° ve140° toplam180°=π olur.','E');
 add(174,'Paydayı temizledikten sonra bölge seçimi','Trigonometrik denklemler','AYT-mat',49,
 'π<x<2π aralığındaki kesirli denklemi sin x değişkenine indirip bulunan sinüs değerlerinin bölge ve tanım koşullarını denetlemeyi ölçer.',
 ['sin2x=2sin x cos x ve tan x=sin x/cos x kullanılarak cos²x+sin x=sin²x elde edilir.','sin²+cos²=1 ile2sin²x−sin x−1=(2sin x+1)(sin x−1)=0 olur.'],
 ['sin x=1 bu aralıkta yoktur;sin x=−1/2 çözümleri7π/6 ve11π/6’dır.','İkisi de özgün paydaları sıfırlamaz. Toplam3π,cevap B’dir;3π/2 zaten tanımsızdır ve çözüm değildir.'],
 'Paydayı temizlerken tanımsız noktaları çözüm kümesine geri eklemek eşdeğerliği bozar;son kökler özgün denkleme göre kontrol edilir.',
 'Sinüs polinomu','Kare ve çift açı terimleri tek sinüs değişkenli ikinci dereceye dönüşür;sonra trigonometrik kökler seçilir.',
 'π<x<2π ve sin x=−1/2 çözümleri toplamı kaçtır?',['2π','5π/2','3π','7π/2','4π'],2,'Üçüncü ve dördüncü bölge kökleri7π/6 ile11π/6’dır;toplam18π/6=3π olur.','B');
 add(175,'Kosinüs karesinden sinüs karesine','Trigonometrik denklem','AYT-mat',50,
 'cos²a−cos2a farkının sin²a olduğunu tanıyıp dar açı koşuluyla sin a’yı sadeleştirerek tanjantı bulmayı ölçer.',
 ['cos2a=cos²a−sin²a olduğundan sol taraf sin²a’dır.','Sağ taraf2sin a cos a’dır;dar açı nedeniyle sin a>0 ve bölme geçerlidir.'],
 ['sin a=2cos a,tan a=2 bul.','1+tan²a=sec²a=5 olduğundan cos a=1/√5 olur. Doğru seçenek C’dir;diğer oranlar bu değere göre farklıdır.'],
 'cos²a ile cos2a’yı aynı ifade saymak sol tarafı sıfırlar;kuvvet ve çift açı farklı matematiksel gösterimlerdir.',
 'Oran üçgeni','tan a=2,karşı2 komşu1 hipotenüs√5 olan dik üçgenle bütün diğer oranları belirler.',
 'Dar açıda tan a=2 ise sin a kaçtır?',['1/√5','2/√5','√5/2','1/2','2/5'],1,'Dik üçgende karşı2,komşu1,hipotenüs√5 seçilebilir. Sinüs karşı/hipotenüs=2/√5’tir.','C');
 add(176,'Sin4x için ikinci derece ve dört kök','Trigonometrik denklemler','AYT-mat',49,
 'cos8x=1−2sin²4x dönüşümüyle ikinci derece kurup geçersiz sinüs değerini eledikten sonra4x’in iki periyodunu taramayı ölçer.',
 ['s=sin4x için2s²+√2s−2=0 olur.','Kökler s=√2/2 ve s=−√2’dir;ikincisi sinüs aralığı dışında olduğundan elenir.'],
 ['0<4x<4π aralığında4x=π/4,3π/4,9π/4,11π/4 bulunur.','Bu dört açının toplamı6π, x değerlerinin toplamı6π/4=3π/2’dir. Doğru seçenek D’dir.'],
 '0<x<π aralığını4x için değiştirmemek son periyottaki iki kökü kaçırır;ölçeklenmiş aralık sonuna kadar taranmalıdır.',
 'Fonksiyon değer aralığı','Cebirsel ikinci derece kökü sinüsün[−1,1] sınırına uymalıdır;−√2 matematiksel kök olsa da trigonometrik çözüm vermez.',
 'sin t=√2/2 ve0<t<2π için kaç çözüm vardır?',['1','2','3','4','5'],1,'Birinci ve ikinci bölgede t=π/4 ve3π/4 olmak üzere iki çözüm bulunur.','D');
 add(177,'Kosinüs karesini ortak çarpan yapma','Trigonometrik denklemler','AYT-mat',50,
 'sin2x=2sin x cos x açılımından sonra1−sin²x=cos²x ile iki ayrı çözüm ailesini çarpanlara ayırmayı ölçer.',
 ['Denklem sin²x+2sin x cos²x=sin²x+cos²x biçiminde yazılır.','Buradan cos²x(2sin x−1)=0 çıkar;iki çarpanın kökleri ayrı alınmalıdır.'],
 ['cos x=0 içinπ/2,3π/2;sin x=1/2 içinπ/6,5π/6 bulunur.','Dört farklı çözümün toplamı2π+π=3π’dir. Doğru seçenek D’dir;cos²x’e bölerek ilk iki kök kaybedilmez.'],
 'cos²x’i önce sadeleştirmek bu çarpan sıfırken gelen geçerli çözümleri siler;eşitlikte ortak çarpan varsa sıfır dalı korunur.',
 'Sıfır çarpım kuralı','Trigonometrik çarpanlar da cebirsel çarpanlar gibi ayrı sıfır olasılıkları üretir;çözüm kümeleri birleşimle alınır.',
 'cos²x(2sin x−1)=0 ifadesinde cos x=0 dalı hangi çözümleri verir? 0<x<2π.',['π/6,5π/6','π/2,3π/2','0,π','π,2π','Yok'],1,'Kosinüs ikinci ve dördüncü eksen kesişimlerinde değil,y ekseni doğrultularında sıfırdır;π/2 ve3π/2 bulunur.','D');
 add(178,'Logaritmik cetvelde sabit oran','Logaritma özellikleri','AYT-mat',51,
 'İki özdeş cetvel arasındaki kaymayı logaritmik uzunluk farkı olarak yorumlayıp eşleşen sayıların oranının sabit olduğunu kullanmayı ölçer.',
 ['Üst42 ilealt28 aynı konumdaysa kayma log42−log28=log(3/2)’dir.','Üst33 vealt x için de aynı kayma log33−log x olmalıdır.'],
 ['log(33/x)=log(3/2) ve pozitif sayılarda logaritmanın birebirliğinden33/x=3/2 yaz.','x=22 bulunur;doğru seçenek E’dir. Eşit fiziksel mesafe sayı farkını değil sayı oranını korur.'],
 '42−28=14 farkını33’ten çıkarmak logaritmik cetveli doğrusal cetvel sanmaktır;uzaklıklar log değerleriyle ölçülür.',
 'Çarpımsal ölçek','Logaritmada bölme fark haline gelir;cetvelin ötelenmesi tüm sayıları aynı oranda çarpmaya karşılık gelir.',
 'Aynı kaymada üst30 alt20’ye denkse üst45 alt hangi sayıya denk gelir?',['25','28','30','35','40'],2,'Oran30/20=3/2’dir.45/x=3/2 eşitliği x=30 verir.','E');
 add(179,'Tabanları2’ye indirip ortalama alma','Logaritma taban değiştirme','AYT-mat',51,
 'log₄x ile log₈(1/x) ifadelerini aynı t=log₂x değişkenine çevirip ortalama koşulundan log₁₆x’i hesaplamayı ölçer.',
 ['log₄x=t/2,log₈(1/x)=−t/3 olur. Logaritmaların tanımlı olması x pozitif olmasını gerektirir; bulunan t değeri böyle bir x üretir.','İki sayının aritmetik ortalaması toplamlarının yarısıdır;burada(t/2−t/3)/2=t/12’dir.'],
 ['t/12=1/2’den t=6 bul.','log₁₆x=t/4=6/4=3/2’dir. Doğru seçenek B’dir;1/x içindeki terslik logaritmanın eksi işaretini oluşturur.'],
 'İkinci terimi+t/3 almak log(1/x)=−log x kuralını atlar;ortalama denkleminin sonucu tümüyle değişir.',
 'Ortak taban','4,8,16’nın2 kuvvetleri olması farklı tabanları aynı değişkenin basit kesirlerine dönüştürür.',
 'log₂x=8 ise log₁₆x kaçtır?',['1','2','3','4','8'],1,'16=2⁴ olduğundan log₁₆x=log₂x/log₂16=8/4=2’dir.','B');
 add(180,'Logaritmada toplam kuralı yoktur','Logaritma özellikleri','AYT-mat',51,
 'Yanlış6=8 sonucunun ilk geçersiz adımını bulurken doğru üstel çarpım kurallarını,logaritmanın toplam üzerinde dağılmamasından ayırmayı ölçer.',
 ['e^(ln a)=a ve e^u e^v=e^(u+v) geçerli özdeşliklerdir.','ln(ab)=ln a+ln b geçerlidir;ln(a+b)=ln a+ln b genel olarak doğru değildir.'],
 ['İlk dört adım6’nın çarpımını ve2+4 toplamını eşdeğer biçimde gösterir.','V. adımda ln(2+4),ln2+ln4’e çevrilmiştir;bu ln6’yı ln8 yapar. İlk hata V,cevap D’dir.'],
 'III. adımı yanlış saymak logaritmanın çarpım kuralını reddetmek olur;ln1+ln2+ln3 gerçekten ln6’ya eşittir.',
 'İlk hata ilkesi','Sonraki adımlar yanlış ara değerden doğru işlemlerle ilerleyebilir;kanıt incelenirken eşdeğerliğin ilk bozulduğu yer aranır.',
 'Hangisi tüm pozitif a,b için doğrudur?',['ln(a+b)=ln a+ln b','ln(ab)=ln a+ln b','ln(a−b)=ln a−ln b','ln(a/b)=ln a/ln b','ln(a+b)=ln a·ln b'],1,'Logaritma çarpımı toplama çevirir. Toplama üzerine genel bir dağılım kuralı yoktur.','D');
 add(181,'64 bölenleri ve tam logaritma','Logaritma ve tam sayılar','AYT-mat',51,
 '64/x tam sayı koşulundan x’i2 kuvvetleriyle sınırlayıp log_x64=6/k’nin hangi üslerde tam olmadığını bulmayı ölçer.',
 ['64=2⁶ olduğundan1’den büyük pozitif bölenler x=2^k,k=1,2,3,4,5,6’dır.','ln64/ln x=log_x64=6/k olur;bu oran ancak k,6’yı bölerse tam sayıdır.'],
 ['k=1,2,3,6 tam oran verdiğinden elenir.','k=4 ve5 için x=16,32 kalır. Toplam48,cevap C’dir;istenen logaritmanın tam olmaması koşuludur.'],
 'İlk koşulu sağlayan bütün bölenleri toplamak ikinci koşulun olumsuzluğunu atlar;tam logaritma verenler özellikle dışlanır.',
 'Asal kuvvet ve taban değiştirme','Logaritmik oran,aynı asal tabandaki üslerin oranına iner;problem bölen kontrolüne dönüşür.',
 'x=2⁵ ise log_x64 kaçtır?',['5/6','6/5','1','5','6'],1,'64=2⁶ olduğundan log_(2⁵)(2⁶)=6/5’tir;tam sayı değildir.','C');
 add(182,'Logaritmanın tam kısmını bloklarla toplama','Logaritma grafiği','AYT-mat',51,
 '⌊log₂n⌋ değerinin ardışık2 kuvvetleri arasındaki sabitliğini kullanarak32 ayrı hesap yerine kuvvet bloklarını saymayı ölçer.',
 ['2^k≤n<2^(k+1) aralığında log₂n’nin tam kısmı k’dir.','n=1 için0;2–3 için1;4–7 için2;8–15 için3;16–31 için4;32 için5 yazılır.'],
 ['Blok katkılarını0·1+1·2+2·4+3·8+4·16+5·1 biçiminde kur.','2+8+24+64+5=103 bulunur. Doğru seçenek D’dir;32 son blokta tek başına yer alır.'],
 '16–32 aralığının tamamına4 yazmak uçtaki log₂32=5 tam değerini kaçırır;sağ uç bir sonraki bloğa geçer.',
 'Basamak fonksiyonu','Tam kısım alma logaritmik eğriyi basamaklara dönüştürür;her basamağın genişliği öncekinin iki katıdır.',
 '1≤n≤8 tam sayıları için⌊log₂n⌋ toplamı kaçtır?',['10','11','12','13','14'],3,'Katkılar0+2·1+4·2+1·3=13’tür.8 sayısı kendi3 basamağındadır.','D');
 add(183,'Üstel farkta ortak3 kuvveti','Üslü denklemler','TYT-mat',41,
 '9^x terimini3^(2x) yapıp ortak3^(2x−2) dışarı alarak2 ve3 asal tabanlarının üslerini ayrı eşitlemeyi ölçer.',
 ['9^x−3^(2x−2)=3^(2x−2)(9−1)=2³3^(2x−2)’dir.','Sağ taraf2^y3⁶ biçimindedir;x,y tam olduğundan asal kuvvetlerin eşitliği üsleri belirler.'],
 ['2 tabanında y=3,3 tabanında2x−2=6 bul.','x=4 ve x+y=7 olur. Doğru seçenek E’dir;üstteki2x−2 ifadesi tek bir üssün tamamıdır.'],
 '3^(2x−2)’yi3^(2x)−2 diye okumak üs parantezini bozarak ortak çarpanı kaybettirir;özgün gösterim dikkatle okunmalıdır.',
 'Asal çarpanların tekliği','Eşit pozitif rasyonel sayıların2 ve3 üsleri aynı olmak zorundadır;negatif tam üsler de bu özelliği korur.',
 '2^a3^b=8·81 ve a,b tam ise a+b kaçtır?',['5','6','7','8','9'],2,'8=2³,81=3⁴ olduğundan a=3,b=4 ve toplam7’dir.','E');
 add(184,'Aynı çubuğun iki parçalama modeli','Logaritmik denklem','AYT-mat',51,
 'Dört veon eş parçanın aynı toplam uzunluğu verdiğini kullanıp log₅(x²/25)’i2log₅x−2 olarak açmayı ölçer.',
 ['Toplam çubuk uzunluğu hem4log₅x hem10log₅(x²/25)’tir.','t=log₅x alınırsa ikinci logaritma2t−2 olur;parça uzunlukları pozitif çıkmalıdır.'],
 ['4t=10(2t−2) eşitliğinden16t=20,t=5/4 bul.','Çubuk uzunluğu4t=5 birimdir;doğru seçenek A’dır. İkinci parça uzunluğu1/2 olduğundan10 parça da aynı5’i verir.'],
 'Parça uzunluklarını doğrudan eşitlemek dört parça ileon parçanın farklı uzunlukta olacağını unutur;eşitlenen bütün çubuktur.',
 'Oran ve korunmuş toplam','Parça sayısıyla tek parça uzunluğu ters orantılıdır;logaritmik ifadeler bu aynı toplamı iki biçimde betimler.',
 '4t=10(2t−2) ise4t kaçtır?',['5','6','8','10','20'],0,'4t=20t−20,16t=20 ve t=5/4 olur.4t=5 bulunur.','A');
 add(185,'İç içe logaritmada pozitif tam üs','Logaritmik denklemler','AYT-mat',51,
 'log₂(log₃n) pozitif tam sayı k olduğunda n=3^(2^k) biçimini çıkarıp100 sınırında hangi değerlerin kaldığını ölçer.',
 ['k≥1 için log₃n=2^k ve n=3^(2^k) olur.','k=1,n=9;k=2,n=81;k=3,n=6561 verir ve sonraki değerler daha da büyür.'],
 ['1<n<100 koşulunda yalnız9 ve81 kaldığını belirle.','Toplam90’dır;doğru seçenek E’dir. k=0 olsaydı n=3 olurdu ama dış logaritma pozitif tam sayı istendiği için bu dal yasaktır.'],
 'Pozitif tam sayı koşuluna0’ı dahil etmek n=3’ü yanlış ekler;dış fonksiyonun çıktısı ile iç logaritmanın değeri ayrı değişkenlerdir.',
 'Üstel büyüme','İç içe ters alma,üsün deüs olduğu hızlı artan dizi oluşturur;üst sınır birkaç terimde bütün adayları tüketir.',
 'log₂(log₃n)=2 ise n kaçtır?',['9','27','81','243','6561'],2,'log₃n=2²=4 olduğundan n=3⁴=81 bulunur.','E');
 add(186,'Taban1’den küçükse logaritma işareti','Logaritma özellikleri','AYT-mat',51,
 'log_a2<0 bilgisinden0<a<1,log₂b>0 bilgisinden b>1 çıkarıp her zaman doğru toplam,fark ve çarpım iddialarını ayırmayı ölçer.',
 ['2>1 iken log_a2’nin negatif olması tabanın0 ile1 arasında olmasını gerektirir.','Tabanı2 olan logaritma artandır;log₂b>0 için b>1 olmalıdır.'],
 ['a>0,b>1 olduğundan a+b>1 ve b−a>0 kesin doğrudur.','ab ise1’in iki yanında olabilir;örneğin a=1/4,b=2 için1/2’dir. I veII,cevap C’dir.'],
 'İki sayı pozitif ve b>1 diye çarpımı da1’den büyük saymak küçük a’nın azaltıcı etkisini unutur;çarpım için ek alt sınır yoktur.',
 'Monotonluk','Logaritmanın artan veya azalan olması tabanın1’e göre konumuna bağlıdır;işaret yorumunda bu ayrım zorunludur.',
 '0<a<1,b>1 iken hangisi kesin pozitiftir?',['a−b','1−b','b−a','ab−1','a−1'],2,'b>1>a olduğundan b−a>0 olur. ab−1’in işareti ise a ve b’nin büyüklüklerine bağlıdır.','C');
 add(187,'Kırpılmış logaritmalardan ln2','Logaritma özellikleri','AYT-mat',51,
 '9,6/0,3=32=2⁵ ilişkisini kullanarak iki gösterilen logaritmanın farkından ln2’yi yaklaşık hesaplayıp negatif çıktının ilk iki hanesini bulmayı ölçer.',
 ['ln9,6−ln0,3=ln32=5ln2 olur.','Gösterilen değerlerle ln2 yaklaşık(2,26+1,20)/5=0,692’dir;istenen ln0,5=−ln2’dir.'],
 ['İki ondalık kırpma hatası hesaba katılınca ln2,0,692 ile0,696 arasında kalır.','Bu aralıktaki negatif değerlerin ilk iki ondalığı−0,69’dur. Doğru seçenek C’dir;makine yuvarlama değililk iki basamağı gösterme kuralı kullanır.'],
 'ln9,6 ile ln0,3’ü toplamak çarpım2,88’in logaritmasını verir;2 kuvvetini ortaya çıkaran işlem bölme,yani farktır.',
 'Hata aralığı','Yaklaşık verilerle bulunan sonuç tam kabul edilmez;istenen iki basamağın bütün olası değerlerde aynı kaldığı doğrulanır.',
 'ln32=5ln2 ise ln(1/2) hangi ifadeye eşittir?',['ln32','−ln32','ln32/5','−ln32/5','5ln32'],3,'ln(1/2)=−ln2 ve ln2=ln32/5 olduğundan sonuç−ln32/5’tir.','C');
 add(188,'Logaritmik karede tek tekrarlı kök','Logaritmik denklem','AYT-mat',51,
 'Karede iki kenarı aynı l seçip alan logaritmasını2ln l yaparak verilen tanımı tam kare denkleme çevirmeyi ölçer.',
 ['Kare alanı l² olduğundan lnA=2ln l’dir.','Tanımdaki çarpım(ln l)² olduğundan t=ln l ile2t=t²+1 yazılır.'],
 ['t²−2t+1=(t−1)²=0’dan t=1 bul.','Kenar l=e,çevre4e olur. Doğru seçenek A’dır;logaritmanın içindeki uzunluk pozitif olduğu için e geçerli kenardır.'],
 'Alanı2l olarak yazmak kare alanı ileçevre katkısını karıştırır;alan l²,çevre4l’dir ve logaritma kuvveti katsayıya indirir.',
 'Yeni tanımı uygulama','Logaritmik dikdörtgen adı standart şekli değiştirmez;yalnız kenarları arasında verilen sayısal koşul eklenmiştir.',
 'ln l=1 ise kenarı l olan karenin alanı nedir?',['e','2e','e²','4e','4e²'],2,'l=e olduğundan alan l²=e²’dir. Çevreyle alanın farklı olması korunur.','A');
 add(189,'Aralıktaki tam sayıların aynılığı','Logaritmik eşitsizlik','AYT-mat',51,
 'Kapalı logaritmik aralıkta yalnız4,5,6 tam sayılarının bulunmasını alt sınır için3<L≤4,üst sınır için6≤U<7 koşullarına çevirmeyi ölçer.',
 ['Alt uç3’ü dışlamalı ama4’ü içermelidir:3<log₅a≤4.','Üst uç6’yı içermeli ama7’yi dışlamalıdır:6≤log₂a<7.'],
 ['İlk koşul125<a≤625,ikinci64≤a<128 verir.','Kesişimde tam a=126,127 vardır. Toplam253,cevap A’dır;kapalı aralık olması logaritmik uçların tam olmasını gerektirmez.'],
 'Alt sınırı doğrudan4,üst sınırı doğrudan6’ya eşitlemek aralığın uçlarını değil,aralıkta bulunan tam sayıları soran ifadeyi yanlış okur.',
 'Tabanla üsse geçiş','Her iki taban1’den büyük olduğundan üstel dönüşüm eşitsizlik yönünü korur;sonuçta iki aralığın kesişimi alınır.',
 'Yalnız4,5,6 tam sayılarını içeren[L,U] aralığı için L hangi koşulu sağlar?',['L=4','3<L≤4','3≤L<4','4<L<5','L≤3'],1,'3 içerilmemeli,4 içerilmelidir. Bu iki şart3<L≤4 aralığını verir.','A');
 add(190,'Üstel farkı asal kuvvetlere ayırma','Üslü denklemler','TYT-mat',41,
 '8^(x−1)’i2 tabanında yazarak farktan3·2^(3x−3) çıkarıp tam sayı üslerde2 ve3’ün tekliğini kullanmayı ölçer.',
 ['2^(3x−1)−8^(x−1)=2^(3x−3)(4−1)=3·2^(3x−3)’tür.','Sağ taraf3^(y+3)·2^(2x+2)’dir;eşitlik2^(x−5)=3^(y+2) biçimine iner.'],
 ['Farklı asal tabanların tam sayı kuvvetleri ancak ikisi de1 olduğunda eşit olabilir.','x−5=0,y+2=0’dan x=5,y=−2 bulunur. xy=−10,cevap A’dır.'],
 '8^(x−1)’i2^(3x−1) yazmak üs çarpımını yanlış dağıtır;doğrusu3(x−1)=3x−3’tür.',
 'Asal çarpanların tekliği','Pozitif veya negatif tam üsler rasyonel sayı üretse de2 ve3 asal çarpanları karşılıklı giderilemez;iki üs sıfırlanır.',
 'Tam sayı u,v için2^u=3^v ise u+v kaçtır?',['−2','−1','0','1','2'],2,'Farklı asal tabanlarda eşitlik yalnız2⁰=3⁰=1 ile mümkündür. u=v=0 olduğundan toplam0’dır.','A');
 add(191,'Logaritma tanımında üç koşul','Logaritma tanım kümesi','AYT-mat',51,
 'Şifreyi bulmak için x−5 tabanının pozitif ve1’den farklı,ikinci derece iç ifadenin depozitif olması koşullarını birlikte uygulamayı ölçer.',
 ['Taban x−5>0 ve x−5≠1 olduğundan x>5,x≠6 gerekir.','−x²+14x−24=−(x−2)(x−12)>0 için2<x<12’dir.'],
 ['Koşullar kesişimi(5,12)\{6} olur.','Tanım kümesindeki tam sayılar7,8,9,10,11’dir. Toplam45,cevap A’dır;6 pozitif taban verse de tabanı1 yaptığı için dışlanır.'],
 'Yalnız logaritmanın içini pozitif yapmak3,4,5,6 gibi tabanı uygunsuz değerleri yanlış ekler;değişken taban ayrı kontrol ister.',
 'İşaret tablosu','Logaritma içindeki parabolun pozitif olduğu aralık bulunur,ardından taban kısıtlarıyla kesiştirilir.',
 'log_(x−2)(x+1) için x=3 geçerli midir?',['Evet;iki ifade pozitif.','Hayır;taban1 olur.','Hayır;iç negatif.','Yalnız x tam değilse','Taban önemsizdir.'],1,'x=3 tabanı1 yapar. Logaritma tabanı pozitif olsa da1 olamaz;bu yüzden ifade tanımsızdır.','A');
 add(192,'Logaritmik yükseklik ve ortak taban','Logaritma grafiği ve alan','AYT-mat',51,
 'x=4’teki iki grafik yüksekliğinden AB=3 bulup ilk alanla sağ apsisi belirlemeyi,sonra CD’yi taban alarak ikinci alanı hesaplamayı ölçer.',
 ['f(4)=2,g(4)=log_(1/4)4=−1 olduğundan AB=3’tür.','ABC alanı6 için½·3·(t−4)=6 ve sağdaki C,D apsisi t=8 olur.'],
 ['f(8)=3,g(8)=−3/2 olduğundan CD=9/2 bul.','ACD’de bu düşey tabana yükseklik8−4=4’tür. Alan½·9/2·4=9,cevap D’dir.'],
 'Aynı şekillerde tabanı eğik AC seçip düşey farkı yükseklik sanmak diklik koşulunu bozar;AB veCD düşey olduğundan yatay mesafe doğru yüksekliktir.',
 'Taban değiştirme','log_(1/4)x=−½log₂x ilişkisi iki grafiğin aynı apsisteki düşey uzaklığını kolay hesaplatır.',
 'x=8’de log₂x ile log_(1/4)x arasındaki düşey uzaklık kaçtır?',['3/2','3','4','9/2','6'],3,'Değerler3 ve−3/2’dir. Aralarındaki uzaklık3−(−3/2)=9/2 olur.','D');
 add(193,'Üç logaritmayı tek orana çevirme','Logaritmik denklemler','AYT-mat',51,
 'Aynı tabanlı logaritmaların toplam–farkını çarpım–bölüm olarak birleştirip log₂3’ü log₄9’a dönüştürmeyi ölçer.',
 ['Sol taraf log₄[(x+5)(x+4)/(x+3)]’tür.','log₂3=log₄9 olduğundan birebirlikle oran9’a eşitlenir;x>0 bütün log içlerini pozitif yapar.'],
 ['(x+5)(x+4)=9(x+3) eşitliğini aç:x²+9x+20=9x+27.','x²=7 olur;pozitif x=√7 seçilir. Doğru seçenek B’dir;negatif kök verilmiş x>0 koşuluna aykırıdır.'],
 'Farklı tabanlı sağ tarafı doğrudan3 sayısına eşitlemek taban değiştirmeyi atlar;log₄9 ilelog₂3 aynı değerdir.',
 'Taban değiştirme','Tabanı karesine çıkarmak log değerini yarıya indirir;bu yüzden içteki sayıyı da karesine çıkarmak değeri korur.',
 'log₂3 ifadesi aşağıdakilerden hangisine eşittir?',['log₄3','log₄6','log₄9','log₈3','log₉4'],2,'log₄9=ln9/ln4=2ln3/(2ln2)=log₂3’tür.','B');
 add(194,'Ardışık logaritmalardan altın oran','Logaritmik denklemler','AYT-mat',51,
 'Küçükten büyüğe sıralı üç logaritmayı n,n+1,n+2 olarak yazıp x+y toplamından a²=a+1 koşulunu çıkarmayı ölçer.',
 ['x=a^n,y=a^(n+1),x+y=a^(n+2) biçiminde yazılır.','a^n>0 olduğundan ortak çarpana bölme1+a=a² verir;a pozitif taban ve1’den farklıdır.'],
 ['a³=a(a+1)=a²+a=2a+1 eşitliğini elde et.','İstenen log_a(2a+1)=log_a(a³)=3’tür. Doğru seçenek D’dir;n’nin ayrı sayısal değeri gerekmez.'],
 'Logaritma değerlerini ardışık yazarken girdilerin deardışık olduğunu varsaymak logaritmanın toplama yerine çarpma ölçeği verdiğini unutur.',
 'Üstel ardışıklık','Logaritmalarda bir birim artış girdide a katına çıkış demektir;üç ardışık değer geometrik oran üretir.',
 'a²=a+1 ise a³ hangi ifadeye eşittir?',['a+1','2a','2a+1','a+2','3a'],2,'a³=a(a+1)=a²+a=(a+1)+a=2a+1’dir.','D');
 add(195,'Faktöriyel oranında ardışık çarpanlar','Logaritma ve faktöriyel','TYT-mat',71,
 'Logaritma toplamını ln(a!/b!)=ln504 biçimine getirip faktöriyel oranının ardışık tam sayı çarpımı olduğunu kullanmayı ölçer.',
 ['3ln2+2ln3+ln7=ln(2³·3²·7)=ln504’tür.','Dolayısıyla a!/b!=504 ve a>b olur;ardışık olmama a−b≥2 koşulunu verir.'],
 ['504=7·8·9 çarpımı b+1’den a’ya ardışık bloktur. İki ardışık sayının çarpımı504 olmaz;daha uzun uygun blok da yoktur.','a=9,b=6 ve a+b=15 bulunur. Doğru seçenek C’dir;tek çarpan504 durumu ardışıklık yasağına takılır.'],
 'a−b’yi doğrudan504 almak faktöriyel oranını sayı farkıyla karıştırır;oran b’den sonraki bütün ardışık çarpanları içerir.',
 'Asal çarpan ve faktöriyel','Logaritma eşitliği çıkarıldığında problem tamamen ardışık çarpanların çarpımına dönüşür;logaritmik yaklaşık değer gerekmez.',
 '9!/6! kaçtır?',['72','126','252','504','720'],3,'6! çarpanları sadeleşir;7·8·9=504 kalır.','C');
 add(196,'Logaritma kümelerinin yansıma kesişimi','Kümeler ve logaritma','AYT-mat',51,
 'log_(1/2)t=−log₂t olduğundan iki kümenin yansıma ilişkisini kullanıp üç ortak log değerin0 ve±u olması gerektiğini ölçer.',
 ['B=−A’dır;A∩B kendi negatifine göre simetrik ve üç elemanlı olduğundan0,±u içerir.','Asıl sayılardan üçü1,t,1/t olur;dördüncü s,çarpım koşulundan7/5’tir.'],
 ['Toplamdan t+1/t=38/5−1−7/5=26/5 bul.','Kareler toplamı1+(7/5)²+(26/5)²−2=28’dir. Doğru seçenek E’dir;dört sayının ayrı olması log kümesinin de dört elemanlı kalmasını sağlar.'],
 'Üç elemanlı simetrik kümede0’ı unutmak çift sayıda±eş gerektiren olanaksız yapı üretir;tek eleman sayısı0’ı zorlar.',
 'Karşılıklı tersler','Logaritma işaretinin ters dönmesi asıl sayıda çarpmaya göre ters almaya karşılık gelir;±u çifti t ve1/t üretir.',
 't+1/t=5 ise t²+1/t² kaçtır?',['15','20','21','23','25'],3,'Eşitliğin karesi t²+2+1/t²=25 verir;2 çıkarılınca23 kalır.','E');
 add(197,'Logaritma oranını kuvvet eşitliğine çevirme','Logaritma ve faktöriyel','AYT-mat',51,
 'Paydaki log farkını bölüm logaritmasına çevirip2log(6!) değerini log((6!)²) yaparak M’yi faktöriyel oranıyla bulmayı ölçer.',
 ['log(10!)−logM=2log(6!) olduğundan10!/M=(6!)² olur.','M pozitif olmalıdır;logaritmanın tanım koşulu bulunan değerde doğrulanır.'],
 ['M=10!/(6!)²=7·8·9·10/6! olarak sadeleştir.','5040/720=7 bulunur. Doğru seçenek E’dir;üs2 yalnız6’yı değil6! değerinin tamamını karesine alır.'],
 'log(6!)² ilelog(6²!) biçimlerini karıştırmak faktöriyel ve üs işlemlerinin sırasını değiştirir;burada(6!)² vardır.',
 'Kuvvet kuralı','Logaritma önündeki katsayı içte üs olur;eşit logaritmalar pozitif girdilerin eşitliğini verir.',
 'logA=2logB ve A,B>0 ise A nedir?',['2B','B/2','B²','√B','2^B'],2,'2logB=log(B²) olduğundan logaritmanın birebirliği A=B² verir.','E');
 add(198,'Logaritmik sütunlarda20 kuvvetleri','Logaritmik ölçek','AYT-mat',61,
 '400,8000,3200000 sayılarını20’nin2,3,5 kuvvetleri olarak tanıyıp logaritma tabanından bağımsız sütun yükseklik oranlarını bulmayı ölçer.',
 ['400=20²,8000=20³,3200000=20⁵’tir.','Aynı tabanda logaritmalar2log20,3log20,5log20 olur;yükseklik oranları2:3:5’tir.'],
 ['Ortadaki3 pay6 cm olduğundan ortak bir pay2 cm’dir.','Diğer yükseklikler4 ve10 cm,toplam14 cm olur. Doğru seçenek E’dir;seçilen taban ortak katsayıyı değiştirir ama oranı değiştirmez.'],
 'Ham sayıların oranını kullanmak yeni grafiğin logaritmik değerleri gösterdiğini unutur;8000/400=20 yükseklik oranı değildir.',
 'Tabandan bağımsız oran','Taban değiştirme bütün log değerlerini aynı sabitle çarpar;göreli sütun yükseklikleri bu sabitte sadeleşir.',
 'Log değerleri2t,3t,5t olan sütunlardan ortadaki9 cm ise diğerlerinin toplamı kaçtır?',['15','18','21','24','27'],2,'3t ölçeği9 cm ise bir pay3 cm’dir. Diğer sütunların toplamı(2+5)·3=21 cm olur.','E');
 add(199,'Aritmetik dizi bağıntısından ortak fark','Aritmetik dizi','AYT-mat',64,
 'a₁=3r bilgisini genel terime yerleştirip a₆=a₂a₄ doğrusal–karesel ilişkisini r≠0 koşuluyla çözmeyi ölçer.',
 ['a_n=a₁+(n−1)r=(n+2)r biçimindedir.','Terimler birbirinden farklı olduğundan r≠0;eşitlikte r çarpanına bölmek geçerlidir.'],
 ['a₆=8r,a₂=4r,a₄=6r olduğundan8r=24r² yaz.','r=1/3 ve a₁₀=12r=4 bulunur. Doğru seçenek D’dir;sıfır ortak fark dalı farklılık koşuluna aykırıdır.'],
 'a₆’yı6r yazmak ilk terimin3r olmasını unutur;genel terimde n−1 adım eklenir.',
 'Çarpım koşulu','Dizi terimleri r’nin katları olduğunda iki terimin çarpımı r² üretir;ek ilişki ölçeği belirler.',
 'a₁=3r olan aritmetik dizide a₇ kaç r’dir?',['6r','7r','8r','9r','10r'],3,'a₇=a₁+6r=3r+6r=9r bulunur. İlk terimden yedinciye altı adım vardır.','D');
 add(200,'Ardışık üçlü toplamından periyot3','Dizi ve periyot','AYT-mat',63,
 'Her ardışık üçlü toplamının eşitliğini yan yana çıkararak a_(n+3)=a_n sonucunu bulup25 terimi bloklara ayırmayı ölçer.',
 ['a_n+a_(n+1)+a_(n+2)=a_(n+1)+a_(n+2)+a_(n+3) eşitliği a_(n+3)=a_n verir.','a₄=a₁=2 ve a₂+a₃=2 olduğundan bir üçlü bloğun toplamı4’tür.'],
 ['İlk24 terim sekiz tam blok oluşturur;toplam8·4=32’dir.','25. terim a₁=2’ye eşit olduğundan genel toplam34 olur. Doğru seçenek A’dır;a₂ ilea₃’ün ayrı değerleri bilinmese de toplam yeterlidir.'],
 'Dizinin sabit olduğunu varsaymak eşit üçlü toplamından gereğinden güçlü sonuç çıkarmaktır;dizi üçlü periyodik olabilir.',
 'Blok toplamı','Periyodik dizide uzun toplam,tam periyotların katkısı ileartan ilk terimlerin katkısına ayrılır.',
 'Periyodu3,ilk üçlüsü2,1,1 olan dizinin ilk10 terimi toplamı kaçtır?',['12','13','14','15','16'],2,'İlk9 terim üç bloktan12 eder.10. terim ilk terim2 olduğundan toplam14’tür.','A');
 add(201,'Tek–çift adımlarda çarpanlar','İndirgemeli dizi','AYT-mat',63,
 'a_(n+1)=a_n[1+(−1)^n/2] bağıntısında tek adımın1/2,çift adımın3/2 çarpanı verdiğini izleyerek ilk terimi bulmayı ölçer.',
 ['n tekse sonraki terim öncekinin yarısı,n çiftse3/2 katıdır.','a₁’den a₅’e dört geçiş vardır;çarpanlar1/2,3/2,1/2,3/2 sırasıyla uygulanır.'],
 ['Toplam çarpan(3/4)²=9/16 olduğundan a₅=(9/16)a₁ yaz.','18=(9/16)a₁ eşitliğinden a₁=32 bulunur. Doğru seçenek D’dir;beşinci terime ulaşmak için beş değil dört adım gerekir.'],
 'Tek ve çift n’de aynı çarpanı kullanmak(−1)^n işaretinin değişimini kaybeder;terim indeksleri tek tek izlenmelidir.',
 'İki adımlı oran','Bir tek ve bir çift geçişin toplam etkisi3/4’tür;dört adım iki aynı çarpan bloğundan oluşur.',
 'Aynı bağıntıda a₁=16 ise a₃ kaçtır?',['4','6','8','12','24'],3,'a₂=16/2=8,a₃=3·8/2=12’dir. İki adımın ortak çarpanı3/4 olur.','D');
 add(202,'Pozitif geometrik oranın seçimi','Geometrik dizi','AYT-mat',65,
 'a₇=a₅+12a₃ bağıntısını ortak a₁r² çarpanına bölüp r² için ikinci derece denklemi çözmeyi ölçer.',
 ['Tüm terimler pozitif olduğundan a₁>0 ve ortak oran r>0’dır.','r⁶=r⁴+12r² eşitliği r⁴−r²−12=0’a indirgenir;r sıfır değildir.'],
 ['(r²−4)(r²+3)=0’dan r=2 bulunur.','a₁=1/2+r=5/2 ve a₈=a₁r⁷=(5/2)·128=320’dir. Doğru seçenek E’dir;negatif oran pozitif terimler koşuluna uymaz.'],
 'a₈’de r⁸ kullanmak genel terimin a_n=a₁r^(n−1) olduğunu unutur;ilk terim zaten bir çarpan içerir.',
 'Değişken değiştirme','r²=t alınırsa denklem t²−t−12 biçimindedir;pozitiflik hem t hem r dalını sınırlar.',
 'İlk terimi5/2,ortak oranı2 olan geometrik dizide a₄ kaçtır?',['10','15','20','25','40'],2,'a₄=(5/2)·2³=20 bulunur. Dördüncü terim ilk terimden üç çarpım adımı uzaktadır.','E');
 add(203,'Aritmetik dizide ilk terim–fark bağı','Aritmetik dizi','AYT-mat',64,
 'a₂=2a₁+1 koşulundan r=a₁+1 çıkarıp uzak iki terimin toplamıyla ilk terimi belirlemeyi ölçer.',
 ['a₂=a₁+r olduğundan r=a₁+1 olur.','a₆+a₂₂=2a₁+(5+21)r=2a₁+26r’dir. Aynı toplam indis ortası14 olan terimin iki katına da eşittir; bu nedenle a₁₄=17 bir kontrol değeridir.'],
 ['2a₁+26(a₁+1)=34 ile28a₁=8,a₁=2/7 bul.','r=9/7 ve a₇=a₁+6r=2/7+54/7=8’dir. Doğru seçenek C’dir;terim değerlerinin tam olması şartı verilmemiştir.'],
 'r’yi veya a₁’i tam sayı seçmeye çalışmak dizinin gerçek terimli olabileceğini gözden kaçırır;kesirli değerler geçerlidir.',
 'İndislerin toplamı','Aritmetik dizide iki terimin toplamı,ortadaki eş uzaklıklı terimlerin toplamına eşittir;indisler fark sayısını belirler.',
 'a₁=2/7,r=9/7 ise a₂ kaçtır?',['1','9/7','11/7','2','18/7'],2,'a₂=a₁+r=2/7+9/7=11/7 bulunur.','C');
 add(204,'İki aritmetik dizide adım oranı','Aritmetik dizi','AYT-mat',64,
 'İlk terimleri eşit iki aritmetik dizide4d_a=6d_b ilişkisinden on adımın ikinci dizide kaç adıma karşılık geldiğini ölçer;metinde sabit dizi dalı açıkça dışlanmamıştır.',
 ['a₅=b₇ eşitliği4d_a=6d_b verir.','a₁₁=b_k eşitliği10d_a=(k−1)d_b olur;standart çözümde ortak farkların sıfır olmadığı kabul edilir.'],
 ['Sıfır olmayan d_b için d_a/d_b=3/2 ve k−1=15 bulunur.','Böylece k=16,anahtar E’dir. Ancak d_a=d_b=0 ise bütün terimler aynı olur ve her k eşitliği sağlar;bu özel dal metinde dışlanmamıştır.'],
 'd_b’ye bölmeden sıfır olasılığını hiç belirtmemek eksik koşulu gizler;16 sonucu sabit olmayan diziler dalında tektir.',
 'İndis ve adım farkı','Terim numarası değil ilk terimden itibaren adım sayısı karşılaştırılır;a₁₁ için on,b_k için k−1 adım vardır.',
 'Sabit olmayan iki dizide ilk terimler eşit ve d_a=2d_b ise a₆ hangi b terimidir?',['b₆','b₈','b₁₀','b₁₁','b₁₂'],3,'a₆ ilk terimden5d_a=10d_b uzaktadır. Bu b₁₁ terimidir.','E');
 all['q-ayt-matematik-204'].keyCheck='conflict';
 all['q-ayt-matematik-204'].note='Anahtar E (16),sabit olmayan aritmetik diziler için elde edilir. Kaynakta ortak farkların sıfırdan farklı olduğu belirtilmiyor;iki dizi aynı sabit dizi seçilirse her pozitif k eşitlikleri sağlar. Eksik koşul görünür tutulmuştur.';
 add(205,'İşaret değiştiren dizi eşitliği','İndirgemeli dizi','AYT-mat',63,
 'a_n+(−1)^n a_(n+1)=2^n bağıntısında tek n’de fark,çift n’de toplam kullanarak dört istenen terimi üretmeyi ölçer.',
 ['n=1 için a₁−a₂=2 ve a₁=0’dan a₂=−2 olur.','n=2 için a₂+a₃=4,a₃=6;sonraki sağ taraflar8,16,32’dir.'],
 ['n=3,4,5 sırasıyla a₄=−2,a₅=18,a₆=−14 verir.','İstenen6−2+18−14=8’dir. Doğru seçenek B’dir;sağdaki2^n değeri her adımda iki katına çıkar.'],
 '(−1)^n işaretini sonraki terimin indeksine göre almak tek–çift düzenini bir adım kaydırır;üs n,mevcut terim indeksidir.',
 'Rekürsiyon','İlk terim ve her komşu çifti bağlayan eşitlik diziyi sırayla belirler;negatif terimler gerçek sayı dizisinde geçerlidir.',
 'Aynı bağıntıda a₁=0 ise a₃ kaçtır?',['−6','−2','2','4','6'],4,'İlk adım a₂=−2,ikinci adım−2+a₃=4 verir. Dolayısıyla a₃=6’dır.','B');
 add(206,'Geometrik oranı aritmetik fark yapmak','Aritmetik ve geometrik dizi','AYT-mat',65,
 'Geometrik dizinin ilk iki teriminden3/2 ortak oranını bulup aynı değeri aritmetik dizinin farkı olarak kullanmayı ölçer.',
 ['b₂/b₁=2/(4/3)=3/2’dir.','b₇=(4/3)(3/2)⁶=243/16 ve a₁₁=a₁+10·3/2=a₁+15 olur.'],
 ['b₇=a₁₁ eşitliğine243/16=a₁+240/16 yaz.','a₁=3/16 bulunur;doğru seçenek D’dir. Aynı3/2 bir dizide çarpan,diğerinde toplama farkı olarak iki ayrı iş görür.'],
 'Aritmetik dizide de(3/2)^10 kullanmak geometrik ve aritmetik ilerlemeyi karıştırır;burada10 kez3/2 eklenir.',
 'Dizi türleri','Geometrikte indis farkı üs,aritmetikte çarpan olur;ortak parametre iki modelin farklı formüllerini bağlar.',
 'Ortak farkı3/2 ve a₁=3/16 olan aritmetik dizide a₁₁ kaçtır?',['183/16','213/16','243/16','273/16','303/16'],2,'a₁₁=3/16+10·3/2=3/16+240/16=243/16 bulunur.','D');
 add(207,'Terim farklarından ortak fark aralığı','Aritmetik dizi','AYT-mat',64,
 'a₃₀−a₂₅ ve a₂₅−a₈ farklarında ilk terimi yok edip5r ve17r ile iki kesin eşitsizliği çözmeyi ölçer.',
 ['Aritmetik dizide a_m−a_n=(m−n)r’dir.','Koşullar5r<53 ve17r>53 biçimine dönüşür;pozitif5,17’ye bölünürken yön değişmez.'],
 ['53/17<r<53/5, yani yaklaşık3,118<r<10,6 bulunur.','Tam sayılar4,5,6,7,8,9,10’dur. Toplam(4+10)·7/2=49,cevap A’dır.'],
 'Terim indekslerinden fark yerine oran almak aritmetik dizinin toplamsal yapısını bozar;ilk terim ancak çıkarma ile sadeleşir.',
 'Tam sayı aralığı','Gerçek ortak fark aralığı bulunduktan sonra sorulan yalnız tam sayı adayları tutulur ve ardışık toplam formülü uygulanır.',
 '3<r<8 ve r tam sayıysa olası r değerleri toplamı kaçtır?',['15','18','22','26','30'],2,'4,5,6,7 değerleri alınır;toplam22’dir. Kesin eşitsizliklerde3 ve8 dahil edilmez.','A');
 add(208,'Ardışık ürünlerin oranından dizi ölçeği','Aritmetik dizi','AYT-mat',64,
 'a₁a₂a₃ ve a₂a₃a₄ çarpımlarını oranlayıp a₄=7a₁ bulmayı,aritmetik farktan terimleri1,3,5,7,9 oranında yazmayı ölçer.',
 ['İlk çarpım2≠0 olduğundan a₁,a₂,a₃ sıfır değildir;iki eşitlik bölünebilir.','a₄/a₁=14/2=7 ve a₄=a₁+3r olduğundan r=2a₁’dir.'],
 ['a₁=t ile ilk beş terim t,3t,5t,7t,9t olur;15t³=2 bulunur.','İstenen5·7·9t³=315·2/15=42’dir. Doğru seçenek C’dir;t’yi küpkök olarak bulmak gereksizdir.'],
 'Aritmetik terimlerin ardışık tam sayılar olacağını varsaymak ortak farkın t’ye bağlı olmasını kaçırır;yalnız oranları belirlenmiştir.',
 'Oranla sadeleştirme','İki çarpımın ortak a₂a₃ kısmı yok olur;üç terimli ürün ilişkisi iki uç terim bağıntısına iner.',
 't,3t,5t çarpımı2 ise5t·7t·9t kaçtır?',['14','21','28','35','42'],4,'İkinci ürünün birinciye oranı(5·7·9)/(1·3·5)=21’dir.2·21=42 bulunur.','C');
 add(209,'Aynı parametreli iki dizi artışı','Aritmetik ve geometrik dizi','AYT-mat',65,
 'a₁=g₁,a₁₃=g₂,a₃₁=g₃ eşleştirmelerinde ardışık geometrik farkların oranını aritmetik indis farklarıyla bulmayı ölçer.',
 ['g₂−g₁=a₁₃−a₁=12r ve g₃−g₂=a₃₁−a₁₃=18r’dir.','Geometrik dizide ardışık farklar da r oranında değişir;r>0 olduğundan ilk fark sıfır değildir.'],
 ['r=(18r)/(12r)=3/2 bulunur. Sonraki fark g₄−g₃=r·18r=27r olur.','a_k−a₃₁=(k−31)r=27r verdiğinden k=58’dir. Doğru seçenek C’dir;ilk terimi hesaplamak gerekmez.'],
 'İndis31’in doğrudan ortak orana bölünmesi terim indeksleriyle değerler arası farkı karıştırır;önce eşleştirilmiş artışlar alınır.',
 'Fark dizisi','Geometrik dizinin ardışık farklarının da geometrik olması,aritmetik indis mesafelerinden ortak oranı buldurur.',
 'Geometrik dizide g₂−g₁=8,g₃−g₂=12 ise g₄−g₃ kaçtır?',['14','16','18','20','24'],2,'Farkların ortak oranı12/8=3/2’dir. Sonraki fark12·3/2=18 olur.','C');
 add(210,'Ortak limit ile nokta değerini ayırma','Limit','AYT-mat',68,
 'İki fonksiyonun aynı L limitine sahip olmasından fark limitinin sıfır olduğunu çıkarırken nokta değerleri ve0/0 oranının belirlenemeyeceğini ölçer.',
 ['Limitler sonluysa farkın limiti limitlerin farkıdır:L−L=0.','Limit bilgisi f(2),g(2) nokta değerlerini zorunlu eşitlemez;fonksiyonlar o noktada süreksiz olabilir.'],
 ['II her zaman doğrudur. III için L≠0 gerekirdi;L=0’da örneğin f=x−2,g=2(x−2) oranı1/2 verir.','I de kesin değildir. Yalnız II,cevap B’dir;oran yasasının sıfır olmayan payda limiti koşulu unutulmaz.'],
 'Aynı limitten aynı nokta değerini çıkarmak sürekliliği verilmemişken varsayar;limit yakındaki değerleri anlatır.',
 'Limit cebirinin koşulları','Toplam ve fark yasası sonlu limitlerle doğrudan çalışır;oran yasası ek olarak payda limitinin sıfır olmamasını ister.',
 'lim f=lim g=0 ise lim(f/g) zorunlu1 midir?',['Evet','Hayır;örneğin f=2g oran2 olabilir.','Evet;f=g olur.','Oran daima0','Oran daima sonsuz'],1,'Aynı sıfır limite giden fonksiyonların hızları farklı olabilir. f=2(x−2),g=x−2 örneğinde oran2’dir.','B');
 add(211,'Parçalı fonksiyonda iki birleşme noktası','Süreklilik','AYT-mat',68,
 'Kaynak görselin üstteki10−x² parçasını da okuyarak0 ve3 geçişlerinde iki tarafın aynı değere ulaşmasını şart koşmayı ölçer.',
 ['x<0 parçası10−x² olduğundan0 sol limiti10 ve orta parçanın0 değeri b’dir.','x>3 parçası(1−x)² olduğundan3 sağ limiti4 ve orta parçanın3 değeri3a+b’dir.'],
 ['0 sürekliliği b=10 verir.3 sürekliliği3a+10=4,a=−2 sonucunu oluşturur.','a+b=8’dir;doğru seçenek E’dir. Parçalar kendi içlerinde polinom olduğundan başka süreklilik koşulu gerekmez.'],
 '10−x² satırını görmeden yalnız orta ve alt parçayı kullanmak iki bilinmeyen için eksik denklem bırakır;özgün PDF üst satırı korunmalıdır.',
 'Sınırda yapıştırma','Parçalı polinomlar yalnız tanım değişen sınırlarda kesintiye uğrayabilir;uç limitlerin eşitliği bütün fonksiyonun sürekliliğini sağlar.',
 'f(x)=10−x²,x<0;ax+b,x≥0 ise0’da süreklilik için b kaçtır?',['0','2','5','8','10'],4,'Sol limit10,sağ limit ve nokta değeri b’dir. Süreklilik b=10 gerektirir.','E');
 add(212,'Delik noktada sadeleşen iki kesir','Limit','AYT-mat',68,
 'Kare payları(x−2)²,(x−3)² olarak ayırıp fonksiyon2 ve3’te tanımsız olsa da sadeleşmiş yakın değerlerden limit almayı ölçer.',
 ['(x²−4x+4)/(x−2)=x−2,x≠2 için geçerlidir.','(x²−6x+9)/(2x−6)=(x−3)/2,x≠3 için geçerlidir.'],
 ['Yakın çevrede f(x)=x−2+(x−3)/2=(3x−7)/2 olur.','2’de limit−1/2,3’te limit1’dir. Toplam1/2,cevap B’dir;fonksiyon değerinin eksikliği limitin bulunmasına engel değildir.'],
 '2 veya3’ü özgün paydada sıfır gördüğünde limit yok demek kaldırılabilir süreksizlikle sonsuz limiti karıştırır.',
 'Yerel eşitlik','Limitte yalnız noktaya yakın ama noktadan farklı girdiler gerekir;sadeleştirme bu çevrede eşitliği korur.',
 'lim_(x→2)(x−2)²/(x−2) kaçtır?',['0','1','2','Sonsuz','Yok'],0,'x≠2 için ifade x−2’dir.2’ye yaklaşınca0’a gider;özgün2 noktasının tanımsız olması sonucu değiştirmez.','B');
 add(213,'Tam bir süreksizlik için parametre eleme','Parçalı fonksiyonda süreklilik','AYT-mat',68,
 '1 ve5 sınırlarında sürekliliği sağlayan a kümelerini ayrı bulup yalnız bir sınırın süreksiz olduğu parametreyi seçmeyi ölçer.',
 ['1’de süreklilik a−1=1,a=2 gerektirir.','5’te süreklilik(5−a)²+12=21,(5−a)²=9 ile a=2 veya8 gerektirir.'],
 ['a=2 iki sınırı da sürekli yapar;diğer a değerleri ikisini de bozarken a=8 yalnız1’i bozar.','a=8 için f(7)=13,f(0)=8 ve fark5’tir. Doğru seçenek C’dir.'],
 'Sadece1’de süreklilik koşulunu çözüp a=2 seçmek sorunun tam bir süreksizlik istediğini ters yorumlar;iki sınırın sonuçları birlikte karşılaştırılır.',
 'Küme farkı','Tam bir koşulun sağlanması,iki süreklilik parametre kümesinin simetrik farkıdır;ortak2 değeri elenir.',
 'Bir parçalı fonksiyonun iki sınırı için süreklilik a∈{2} ve a∈{2,8} koşullarını gerektiriyorsa tam bir sınırda süreksizlik hangi a’dadır?',['0','2','4','6','8'],4,'a=8 ikinci sınırı sürekli,ilkini süreksiz yapar. a=2 ikisini sürekli yapar;diğerleri iki süreksizlik oluşturur.','C');
 add(214,'Üstel–logaritmik limitte ortak sıfırların giderilmesi','Limit ve logaritma','AYT-mat',68,
 'e^(3ln(x²−1)+2ln(x³−1)−5ln(x−1)) ifadesini çarpım–bölüm kuvvetine çevirip(x−1)⁵ çarpanını sadeleştirmeyi ölçer.',
 ['x>1 olduğundan bütün log içleri pozitif,e^(lnu)=u uygulanabilir.','x²−1=(x−1)(x+1),x³−1=(x−1)(x²+x+1)’dir.'],
 ['Üstel ifade[(x²−1)³(x³−1)²]/(x−1)⁵ olur;ortak kuvvetler tamamen gider.','Kalan(x+1)³(x²+x+1)²,x→1⁺ için2³·3²=72 verir. Doğru seçenek E’dir. Sağdan yaklaşım, özgün logaritmalardaki x−1 ifadesinin pozitif kalmasını sağlar; sadeleşmiş polinom ise1 noktasında doğrudan süreklidir.'],
 'Logaritmalı f(x)’in tek tek terimlerini sonsuza götürüp işlem yapmak∞−∞ belirsizliğini çözmez;önce üstel ifadenin tek çarpımı kurulmalıdır.',
 'Çarpanlara ayırma','Paydaki sıfır dereceleri3+2=5,paydadaki5 ile eşleşir;sonlu limit bu ortak mertebeden çıkar.',
 'lim_(x→1)(x³−1)/(x−1) kaçtır?',['1','2','3','4','6'],2,'x³−1=(x−1)(x²+x+1) olarak ayrılır. Sadeleştirilmiş ifadenin1 değeri3’tür.','E');
 add(215,'Parça sırasıyla iki adaydan birini seçme','Süreklilik','AYT-mat',68,
 'Sürekli parçalı fonksiyonun b sınırından başlayıp a için çıkan1 ve4 adaylarını a<b parça düzeniyle elemeyi ölçer.',
 ['b’de5b−8=7 olduğundan b=3’tür.','a’da a²−4=5a−8, yani(a−1)(a−4)=0 olur.'],
 ['Parçaların sıralı tanımı a<b gerektirir;b=3 olduğundan a=4 elenir ve a=1 kalır.','a+b=4 bulunur;doğru seçenek A’dır. Her polinom parçası içinde ayrıca bir süreksizlik yoktur.'],
 'a=4’ü tutmak orta parçanın aralığını ters çevirir ve ilk/son tanımların çakışmasına yol açar;parça sınırlarının sırası korunmalıdır.',
 'Tanım kümesinin bölünmesi','Parçalı kuralda aralıklar birbirini dışlayıp gerçel doğruyu tamamlamalıdır;parametre kökleri bu yapısal koşula da uymalıdır.',
 'a∈{1,4},b=3 ve a<b ise a+b kaçtır?',['3','4','5','6','7'],1,'a<b şartına yalnız a=1 uyar. Toplam1+3=4’tür.','A');
 add(216,'Üstel limitin pozitifliğiyle kökü eleme','Limit','AYT-mat',68,
 'Payda x−a’da sonlu limit bulunabilmesi için a’nın pay kökü olması gerektiğini ve eşit3^b limitinin pozitifliğiyle a=2 dalının elendiğini ölçer.',
 ['Pay(x−2)(x−5)’tir;a=2 veya5 olmadığı durumda sonlu iki taraflı limit elde edilemez.','a=2’de sadeleşen limit−3,a=5’teki limit3’tür;3^b her gerçek b için pozitiftir.'],
 ['Bu yüzden a=5,c=3 seçilir.','Sürekli g(x)=3^x için3^b=c=3,b=1 olur. a+b+c=5+1+3=9,cevap D’dir.'],
 'a=2 ve5’i eşit derecede geçerli saymak ortak limitin üstel fonksiyon değeri olduğunu kullanmamaktır;negatif−3 değeri olanaksızdır.',
 'Değer aralığı','Bir fonksiyonun pozitif görüntü kümesi,diğer fonksiyonun parametre adayını sayısal limit hesabından sonra eleyebilir.',
 '3^b=3 ve b gerçek ise b kaçtır?',['−1','0','1','2','3'],2,'Aynı pozitif ve1’den farklı tabanda3^b=3¹ eşitliği b=1 verir.','D');
 add(217,'İki sürekli fonksiyonda ortak a','Parçalı fonksiyon sürekliliği','AYT-mat',68,
 'f’nin x=a sınırında bulunan parametreyi g’nin x=1 sınırındaki süreklilik eşitliğine taşıyarak ab’yi hesaplamayı ölçer.',
 ['f’de2a+2=a−1 süreklilik koşuludur.','g’de a+1=3+b koşulu vardır;ilk parça1 noktasını içerir ama sağ limit deaynı değere ulaşmalıdır.'],
 ['İlk eşitlik a=−3 verir;ikincide−3+1=3+b ile b=−5 bulunur.','ab=15’tir;doğru seçenek D’dir. İki parametre negatif olsa da çarpım pozitiftir.'],
 'f’nin sınırını0 almak grafik verilmediği için varsayılmış bir noktada eşitlemektir;parçaların değiştiği nokta x=a’dır.',
 'Birleşme noktası','Süreklilik yalnız kuralın değiştiği sınırda sol ve sağ değerleri eşitlemeyi gerektirir;parametre sınırın kendisi deolabilir.',
 '2a+2=a−1 ise a kaçtır?',['−5','−3','−1','1','3'],1,'Her iki taraftan a ve2 çıkarılınca a=−3 bulunur.','D');
 add(218,'Karekök eşleniğiyle0/0 giderme','Limit','AYT-mat',68,
 'Paydaki1−√x faktörünü eşlenikle x−1’e dönüştürüp paydanın(x−1)(8−x) çarpanıyla sadeleştirmeyi ölçer.',
 ['1−√x=(1−x)/(1+√x)=−(x−1)/(1+√x)’tir.','−x²+9x−8=(x−1)(8−x) olur;diğer pay faktörü∛x−2,1’de−1’dir. Karekök ve küpkök bu noktanın yakınında süreklidir; ortak sıfır giderildikten sonra kalan faktörlere doğrudan değer verilebilir.'],
 ['Ortak x−1 giderilince−(∛x−2)/[(1+√x)(8−x)] kalır.','x=1 yerleştirildiğinde−(−1)/(2·7)=1/14 bulunur. Doğru seçenek D’dir;küpkök faktörünü deeşlenikle açmaya gerek yoktur.'],
 'İkinci pay faktörünün1’de sıfır olduğunu sanmak∛1−2=−1 hesabını kaçırır;belirsizliği yalnız ilk faktör oluşturur.',
 'Yerel sıfır çarpanı','0/0 limitinde her parçayı açmak gerekmez;paydayla ortak sıfırı taşıyan faktörün rasyonelleştirilmesi yeterlidir.',
 'lim_(x→1)(1−√x)/(x−1) kaçtır?',['−1','−1/2','0','1/2','1'],1,'Eşlenikle ifade−1/(1+√x) olur.1’de limit−1/2’dir.','D');
 add(219,'Sürekli çarpımda nokta değerini onarma','Limit ve süreklilik','AYT-mat',68,
 'Grafikte f’nin3’te limit4,nokta değeri7 olduğunu ayırıp çarpımın sürekliliğinden g(3)’ün14 limitinden farklı olmasını hesaplamayı ölçer.',
 ['Açık nokta iki kolun(3,4)’e yaklaştığını;dolu nokta f(3)=7 olduğunu gösterir.','lim g(x)=14 olduğundan çarpım limiti4·14=56’dır.'],
 ['f·g sürekliliği(f·g)(3)=lim(f·g)=56 gerektirir.','7g(3)=56’dan g(3)=8 bulunur. Doğru seçenek C’dir;g’nin kendisinin sürekli olduğu verilmemiştir.'],
 'lim g=14 bilgisinden g(3)=14 demek soru­nun onarılması gereken nokta değerini yanlış sabitler;yalnız çarpım süreklidir.',
 'Kaldırılabilir süreksizlik','İki fonksiyonun nokta değerleri,limit değerlerinin ters oranıyla çarpımda birbirini dengeleyebilir.',
 'lim f=3,f(2)=6,lim g=10 ve fg,2’de sürekliyse g(2) kaçtır?',['3','5','6','10','20'],1,'Çarpımın limiti30’dur.6g(2)=30 olduğundan g(2)=5 bulunur.','C');
 add(220,'Ters fonksiyonda sonlu limit koşulu','Ters fonksiyon ve limit','TYT-mat',91,
 'f=ax+b ve f⁻¹=(x−b)/a ifadelerinden x→b’de sıfır paydanın sonlu limit için payı da sıfırlaması gerektiğini ölçer.',
 ['Oran a(ax+b)/(x−b)’dir;sonlu c için payın b’deki değeri ab(a+1)=0 olmalıdır.','a≠0 olduğundan b=0 veya a=−1 olur;ayrıca f(1)=a+b=3’tür.'],
 ['b=0 dalında a=3,oran9 ve c=9 çıkar. a=−1 dalında b=4,fonksiyon tersine eşit olduğundan oran1,c=1’dir.','Farklı c değerleri toplamı9+1=10,cevap C’dir.'],
 'Payda sıfırsa limit mutlaka sonsuzdur demek aynı anda payın da sıfırlanabileceğini unutmak demektir;parametreler bu giderilmeyi belirler.',
 'Çıkarılabilir tekillik','İstenen sonlu limit parametreleri iki dala ayırır;her dalda cebirsel sadeleşme ayrı kontrol edilir.',
 'f(x)=3x ise f(x)/f⁻¹(x),x≠0 için kaçtır?',['1','3','6','9','12'],3,'f⁻¹(x)=x/3’tür. Oran3x/(x/3)=9 olur;sıfır noktasında da limiti9’dur.','C');
 add(221,'Parçalı polinomlarda iki sınır değeri','Süreklilik','AYT-mat',68,
 'a sınırındaki ilk polinomun a²−a²+6 sadeleşmesini ve b sınırındaki doğrusal parçaların değer eşitliğini kullanmayı ölçer.',
 ['x=a’da ilk parça6,orta parçanın limiti2a+a=3a’dır.','x=b’de orta değer2b+a,sağ limit11−2b+b=11−b olur.'],
 ['6=3a’dan a=2 bul. İkinci koşul2b+2=11−b,3b=9,b=3 verir.','ab=6’dır;doğru seçenek B’dir. a<b sırası2<3 ile sağlanır ve fonksiyonun parçaları düzenli biçimde birleşir.'],
 'İlk parçada−ax terimini−a veya−x sanmak sınırda a²’nin sadeleşmesini bozar;parametre ilegirdi ayrı okunmalıdır.',
 'Parametrenin sınırda kullanımı','Aynı a hem katsayı hem birleşme apsisi olduğundan x=a yerine koymak ilk polinomu sabit6’ya indirir.',
 'x=a için x²−ax+6 ifadesi kaçtır?',['0','a','a²','6','a+6'],3,'x=a yazınca a²−a·a+6=6 olur. Aynı iki kare terimi birbirini yok eder.','B');
 add(222,'Sıfır çarpım limiti ve sonlu oran','Limit','AYT-mat',68,
 'f(a)=a³+2 pozitif olduğundan çarpım limitinin sıfırlığını g(a)=0’a bağlayıp sonlu oran koşuluyla payın da sıfır olmasını ölçer.',
 ['a>0 olduğundan f(a)>0;polinom sürekliliği g(a)=0 gerektirir.','Oran limitinin sonlu−2 olması f(a)−10=a³−8=0,a=2 koşulunu verir.'],
 ['g’nin bir kökü2,diğeri t olsun:g=(x−2)(x−t). f−10=2(x−2)(x+2)’dir.','Limit8/(2−t)=−2 olduğundan t=6 bulunur. a+b+c=2+2+6=10,cevap C’dir.'],
 'Çarpım limiti0 diye f(a)=0 seçmek f(a)>0 bilgisini ihmal eder;pozitif parametre hangi çarpanın sıfır olduğunu kesinleştirir.',
 'Ortak kök ve sadeleşme','0/0 oranı aynı x−2 çarpanını taşır;sonlu limit geriye kalan kökün yerini belirler.',
 '8/(2−t)=−2 ise t kaçtır?',['−6','−2','2','4','6'],4,'8=−4+2t eşitliğinden2t=12,t=6 bulunur. Payda−4 sıfır değildir.','C');
 add(223,'Sürekli farkın sıfır olmadan işaret koruması','Süreklilik ve ara değer','AYT-mat',68,
 'f(x)−x ve g(x)+x sürekli farklarının hiçbir yerde sıfır olmamasını,−1’deki işaretlerinin bütün gerçel doğru boyunca korunmasıyla ilişkilendirmeyi ölçer.',
 ['F=f−x için F(−1)=1>0 ve hiçbir yerde0 olmaz.','G=g+x için G(−1)=−1<0 ve hiçbir yerde0 olmaz;sürekli fonksiyon işaret değiştirirse arada0 alırdı.'],
 ['Dolayısıyla f(1)−1>0, f(1)>1 bulunur.','g(1)+1<0, g(1)<−1 olur. Sıra g(1)<0<f(1),cevap D’dir;noktasal koşul süreklilikle küresel işarete dönüşür.'],
 'f(x)≠x ifadesinden f’nin x’ten bazen küçük bazen büyük olabileceğini düşünmek süreklilik ve ara değer teoremini birlikte kullanmamaktır.',
 'Ara değer teoremi','Sıfır almayan sürekli fonksiyon bağlı bir aralıkta işaret değiştiremez;doğrularla fark almak bu kuralı uygulanabilir yapar.',
 'Sürekli H,hiç0 almıyor ve H(0)>0 ise H(5) için ne kesindir?',['Negatif','Pozitif','Sıfır','H(0)’a eşit','1’e eşit'],1,'Negatif olsaydı0 ile5 arasında ara değer teoremi gereği0 alırdı. Bu yasak olduğundan H(5)>0’dır.','D');
 add(224,'Türev grafiği pozitifken fonksiyon artar','Türevin işareti','AYT-mat',81,
 'Verilen grafiğin f değil f′ olduğunu fark ederek0–2 aralığındaki pozitif türevden f değerlerinin artan sırasını bulmayı ölçer.',
 ['f′ grafiği0–1 arasında pozitif,1’de sıfır,1–2 arasında yine pozitiftir.','Tek noktada f′=0 olması fonksiyonun artışını bozmaz;iki yanda işaret değişimi yoktur.'],
 ['0’dan1’e f artar ve f(0)<f(1) olur.','1’den2’ye deartarak f(1)<f(2) verir. Doğru sıralama f(0)<f(1)<f(2),cevap A’dır.'],
 'Türev grafiğindeki düşen sol kolu f’nin azalması sanmak eğimin değişimiyle fonksiyonun değişimini karıştırır;önemli olan f′’nin x eksenine göre işaretidir.',
 'Durağan nokta','Türev sıfır olsa bile işaret değişmiyorsa yerel ekstremum oluşmayabilir;burada x=1 artan fonksiyonun durağan noktasıdır.',
 'f′ iki tarafta pozitif ve yalnız x=1’de0 ise f için ne söylenir?',['1’de kesin maksimum','1’de kesin minimum','Bu bölgede artar.','Bu bölgede azalır.','Sabittir.'],2,'Pozitif türev artışı gösterir. Tek sıfır noktası iki yandaki artışı tersine çevirmez.','A');
 add(225,'Teğet eğiminden eğrideki parametre','Teğet ve türev','AYT-mat',76,
 'P’nin apsisinin deparametre a olduğunu kullanarak y=a/(a+x) eğrisinde b’yi1/2 bulup teğet eğimini−1/8’e eşitlemeyi ölçer.',
 ['P(a,b) eğri üzerinde olduğundan b=a/(2a)=1/2’dir;payda nedeniyle a≠0’dır.','Türev y′=−a/(a+x)² ve x=a’da eğim−1/(4a)’dır.'],
 ['−1/(4a)=−1/8 eşitliğinden a=2 bulunur.','P(2,1/2) teğette yerine konur:1/2=−2/8+c,c=3/4. Toplam13/4,cevap C’dir.'],
 'Teğet doğrusundaki c’yi b sanmak ordinatla y ekseni kesişimini karıştırır;P’nin apsisi2 olduğu için teğetin sabit terimi farklıdır.',
 'Teğet iki koşulu','Teğet hem noktadan geçer hem eğriyle aynı eğime sahiptir;bir koşul parametreyi,diğeri doğru sabitini belirler.',
 'Eğim−1/8 ve P(2,1/2)’den geçen doğrunun y kesişimi kaçtır?',['1/4','1/2','3/4','1','5/4'],2,'1/2=−2/8+c olduğundan c=1/2+1/4=3/4’tür.','C');
 add(226,'Fiyat artışıyla azalan müşteri gelirini maksimize etme','Maksimum–minimum','AYT-mat',87,
 'Her5 TL artışta50 müşteri kaybını n artış sayısıyla modelleyip fiyat×müşteri çarpımındaki aşağı açılan parabolün tepesini bulmayı ölçer.',
 ['n artıştan sonra fiyat40+5n,müşteri1000−50n olur.','Gelir R(n)=(40+5n)(1000−50n)=40000+3000n−250n²’dir.'],
 ['Tepe n=−3000/[2(−250)]=6 artışta oluşur.','Aylık fiyat40+5·6=70 TL bulunur. Doğru seçenek D’dir;bu noktada700 müşteri kalır ve kapasite koşulu aşılmaz.'],
 'Geliri yalnız bir müşterinin ücretiyle ölçmek fiyat arttıkça kaybolan müşteri etkisini yok sayar;toplam gelir iki değişkenin çarpımıdır.',
 'İkinci derece optimizasyon','Doğrusal fiyat ve müşteri modellerinin çarpımı parabol üretir;negatif baş katsayı tepe noktasının maksimum olduğunu garanti eder.',
 'R(n)=100+40n−5n² fonksiyonu hangi n’de maksimumdur?',['2','3','4','5','8'],2,'Tepe apsisi−40/(2·−5)=4’tür. Negatif baş katsayı nedeniyle bu değer maksimum verir.','D');
 add(227,'Bileşkenin zincir türevindeki2x','Zincir kuralı','AYT-mat',80,
 'g(x²) türevinde dış g′ değerine iç x² türevi2x’i çarparak−1 noktasındaki işareti doğru kullanmayı ölçer.',
 ['f′(x)=2xg′(x²)+3kx² olur.','x=−1 için iç g′ girdisi1,çarpan2x=−2’dir;verilen f′(−1)=g′(1)=2’dir.'],
 ['2=−2·2+3k eşitliğini kur.','3k=6,k=2 bulunur. Doğru seçenek A’dır;g′(1) pozitif olsa da iç türev−2 katkısı negatiftir.'],
 'g(x²)’nin türevini yalnız g′(x²) almak zincir kuralının iç türev çarpanını atlar ve k’yı yanlış verir.',
 'Bileşkede nokta izleme','Türev dış fonksiyona hangi girdinin gittiğini dehesaplar;−1’in karesi1 olduğu için verilen g′(1) kullanılabilir.',
 'h(x)=g(x²) ve g′(4)=3 ise h′(−2) kaçtır?',['−12','−6','3','6','12'],0,'h′(−2)=2(−2)g′(4)=−4·3=−12 bulunur.','A');
 add(228,'Bileşke türevinin iki sıfır kaynağı','Zincir kuralı','AYT-mat',80,
 '(g∘f)′=g′(f(x))f′(x) çarpımının hem iç türevin sıfırından hem dış türevin2 girdisinde sıfır olmasından çözüm aldığını ölçer.',
 ['f′(x)=2x+1 olduğundan x=−1/2 bir çözümdür.','g′ yalnız2’de sıfırdır;bu çarpanın sıfırlığı f(x)=2,x²+x−6=0 gerektirir.'],
 ['f(x)=2 denklemi x=−3 veya2 verir;üç kök birbirinden farklıdır.','Çarpım(−1/2)(−3)·2=3 bulunur. Doğru seçenek C’dir;yalnız f(x)=2 köklerini saymak iç türev dalını eksiltir.'],
 'Dış g′’nin2’de sıfır olmasını x=2 tek çözüm sanmak g′’nin girdisinin x değil f(x) olduğunu unutur.',
 'Sıfır çarpım kuralı','Zincir türevi iki çarpan üretir;her birinin sıfır kümesi bileşkenin durağan noktalarına katkı sağlar.',
 'f=x²+x−4 için f′=0 çözümü nedir?',['−2','−1','−1/2','0','1/2'],2,'Türev2x+1’dir.2x+1=0 eşitliği x=−1/2 verir.','C');
 add(229,'Mutlak türevden doğruların eğim büyüklüğü','Türev ve doğrusal grafik','AYT-mat',76,
 'Birim karelerde doğruların dikliklerini karşılaştırıp |f′|>|g′|>|h′| sırasını renkli doğrulara eşleyerek y kesişimlerini okumayı ölçer.',
 ['Doğrusal fonksiyonun türevi sabit eğimidir;mutlak türev eğimin diklik büyüklüğünü verir.','En dik kırmızı azalan f,ondan az dik mavi azalan g,en yatık kahverengi artan h’dir.'],
 ['İkinci şeklin en yüksek yatay çizgisini kırmızıya,ortayı maviye,altı kahverengiye bağla.','İlk şekilde y ekseninde kahverengi en alt,kırmızı orta,mavi üsttedir. h(0)<f(0)<g(0),cevap D’dir.'],
 'Negatif eğimli doğrunun türev mutlak değerini negatif çizmek mutlak değeri unutmak olur;şekil2’de üç değer de pozitiftir.',
 'Eğim ve başlangıç değeri','Eğim büyüklüğü doğru etiketlerini belirler;istenen nokta değerleri ise bundan sonra ayrı y kesişimlerinden okunur.',
 'Doğruların eğimleri−3,2,1/2 ise en büyük mutlak türev hangisinindir?',['−3 eğimli','2 eğimli','1/2 eğimli','Üçü eşit','İşaret bilinmez'],0,'Mutlak değerler3,2,1/2’dir. En büyük3 olduğundan−3 eğimli doğru seçilir.','D');
 add(230,'Ortak teğette hem eğim hem sabit','Teğet doğrusu','AYT-mat',76,
 'Parabole2’de ve kübiğe1’de çizilen aynı teğetin eğimlerini ve y kesişimlerini eşitleyerek iki parametreyi belirlemeyi ölçer.',
 ['f teğeti y=(4+a)x−4 biçimindedir;f(2)=4+2a,f′(2)=4+a olur.','g=bx³ teğeti1’de y=3bx−2b’dir.'],
 ['Ortak doğrunun sabitlerinden−4=−2b,b=2 bul.','Eğimlerden4+a=3b=6,a=2 çıkar. ab=4,cevap B’dir;yalnız eğim eşitliği iki bilinmeyeni belirlemeye yetmez.'],
 'Aynı eğimli iki doğruyu aynı doğru saymak paralel doğruların farklı kesişim sabitleri olabileceğini unutur;teğetin kendisi ortak olmalıdır.',
 'Nokta–eğim formu','y−f(t)=f′(t)(x−t) her iki eğri için doğruyu açık katsayı biçiminde üretir.',
 'g(x)=2x³ eğrisinin1’deki teğetinin y kesişimi kaçtır?',['−6','−4','−2','2','6'],1,'g(1)=2,g′(1)=6 olduğundan y−2=6(x−1),y=6x−4’tür.','B');
 add(231,'Parametreli üslerde simetrik toplamlar','Türev kuralları','AYT-mat',78,
 'a x^a+b x^b fonksiyonunda katsayı ileüssün aynı parametre olduğunu izleyip a+b,a²+b² bilgilerinden ikinci türevi hesaplamayı ölçer.',
 ['f(1)=a+b=6 ve f′(1)=a²+b²=20’dir.','ab=[(a+b)²−(a²+b²)]/2=(36−20)/2=8 olur.'],
 ['f″(1)=a²(a−1)+b²(b−1)=a³+b³−20 yaz.','a³+b³=6³−3·8·6=72 olduğundan sonuç52’dir. Doğru seçenek E’dir;parametreleri ayrı çözmek zorunlu değildir. Kontrol için a,b değerleri2 ve4 bulunabilir; ikinci türev katkıları4 ve48 olarak aynı52 toplamını verir.'],
 'a x^a türevini a x^(a−1) yazmak öndeki a katsayısını kaybeder;doğrusu a²x^(a−1)’dir.',
 'Simetrik özdeşlik','a³+b³=(a+b)³−3ab(a+b) bağıntısı türevden istenen toplamı verilen simetrik bilgilerle buldurur.',
 'a+b=6,ab=8 ise a³+b³ kaçtır?',['52','64','72','80','96'],2,'6³−3·8·6=216−144=72 bulunur.','E');
 add(232,'Eksensiz ızgarada ölçeği türevle kurma','Parabol ve türev grafiği','AYT-mat',76,
 'Eş kareli grafikte f′ doğrusunun eğimi1 olduğu için f″=1 bulup kare kenarının sayısal birimini parabolden belirlemeyi ölçer.',
 ['Eş kareli düzlemde f′ doğrusu her bir kare sağa bir kare yukarı gider;eğim1’dir.','Parabolün tepesinden3 kare yatay uzaklıktaki nokta2 kare yukarıdadır;bir karenin kenarı s olsun.'],
 ['f″=1 olduğundan tepeye göre yükseklik½(3s)²=2s,buradan s=4/9 bulunur.','Tepe apsisinde f′=0 olmalı;x ekseni f′ üzerindeki bu seviyedir. Parabol tepesi bu eksenden2 kare yukarıdadır;minimum2s=8/9,cevap E’dir.'],
 'Izgaradaki bir kareyi otomatik1 birim saymak eksenler silindiğinde ölçeğin verilmediğini gözden kaçırır;türev eğimi ölçeği geri kurar.',
 'Türevin sıfırı ve tepe','Parabol tepesinin apsisi türev doğrusunun x kesişimiyle aynıdır;bu bağlantı görünmeyen yatay eksenin yerini belirler.',
 'f″=1 olan parabolde tepeye yatay2 birim uzaklıkta yükseklik farkı kaçtır?',['1','2','3','4','8'],1,'Parabol tepe biçiminde½(x−h)²+k’dir. İki birim uzaklıkta fark½·2²=2 olur.','E');
 add(233,'Saatlik yakıtı100 kilometreye dönüştürme','Maksimum–minimum','AYT-mat',87,
 'Verilen f(V)’nin saatlik tüketim olduğunu fark edip100 kilometrelik yolun100/V saat süreceğini kullanarak doğru optimizasyon fonksiyonunu kurmayı ölçer.',
 ['Toplam yakıt F(V)=100f(V)/V’dir;V>0 olmalıdır.','Bu ifade5V²−700V+26500=5(V−70)²+2000 olarak yazılır.'],
 ['Kare terimi en az0 olduğundan minimum V=70 km/saat hızında oluşur.','En az yakıt2000 birimdir;doğru seçenek B’dir. f(V)’nin kendisini minimize etmek sabit zaman problemini çözer ve burada doğru hedef değildir.'],
 'Saatlik tüketimi yol tüketimi sanmak hız arttığında yol süresinin kısaldığını atlar;yakıt oranı süreyle çarpılmalıdır.',
 'Birim analizi','Birim/saat tüketim ile saat cinsinden100/V süre çarpılınca toplam birim yakıt elde edilir.',
 'Saatlik tüketim f(V)=V² ise100 kilometrede yakıt hangi ifadedir?',['V²','100V','100V²','V/100','100/V²'],1,'Yol süresi100/V saattir. Toplam V²·100/V=100V birim olur.','B');
 add(234,'Artma–azalma sınırlarından türevi kurma','Türevin işareti','AYT-mat',81,
 'Kübik fonksiyonun1 ve5’te değişen monotonluk yönlerini ikinci derece türevin kökleri olarak kullanıp baş katsayı3 ile türevi belirlemeyi ölçer.',
 ['f′=3x²+2ax+b ve işaretleri dışta pozitif,içte negatiftir.','Türevin kökleri1,5 olduğundan f′=3(x−1)(x−5)=3x²−18x+15 olur.'],
 ['Katsayı eşleştirmeyle2a=−18,a=−9 ve b=15 bul.','f(2)=8−36+30+1=3’tür. Doğru seçenek B’dir;1 maksimum,5 minimum apsisleridir ama f kökleri değildir.'],
 'Monotonluk değişen1 ve5’i f’nin kökü sanmak fonksiyon değeriyle türev kökünü karıştırır;bu noktaların y değerleri verilmemiştir.',
 'Türevden polinoma dönüş','Kökler ve baş katsayı türevi tam belirler;f’nin sabit terimi1 zaten verildiği için değer doğrudan hesaplanır.',
 'f′=3(x−1)(x−5) ise f hangi aralıkta azalır?',['(−∞,1)','(1,5)','(5,∞)','Tümünde','Hiçbirinde'],1,'İki kök arasında bir çarpan pozitif,diğeri negatiftir;f′<0 olduğu için f azalır.','B');
 add(235,'Grafikten zincir türevinin iki çarpanı','Zincir kuralı','AYT-mat',80,
 'f doğrusundan f(1)=2 ve f′(1)=2’yi,g′ doğrusundan g′(2)=1’i okuyarak bileşke türevini hesaplamayı ölçer.',
 ['Mavi f doğrusu(0,0),(1,2)’den geçer;f(x)=2x’tir.','Kırmızı g′ doğrusu(0,3),(3,0)’dan geçer;g′(x)=3−x olur.'],
 ['(g∘f)′(1)=g′(f(1))f′(1)=g′(2)·2 yaz.','g′(2)=1 olduğundan sonuç2,cevap B’dir. Grafikteki kırmızı eğrinin g değil g′ olduğu özellikle korunmalıdır. Bu yüzden kırmızı doğrunun kendisi tekrar türevlenmez.'],
 'g′(1) değerini kullanmak dış türevin girdisinin f(1)=2 olduğunu unutur;zincir kuralında nokta iç fonksiyonla taşınır.',
 'Grafik ve zincir kuralı','Doğruların eğimleri ve nokta değerleri farklı roller üstlenir;hangi grafiğin türev olduğu doğru okunmalıdır.',
 'f=2x,g′=3−x ise(g∘f)′(1) kaçtır?',['1','2','3','4','6'],1,'g′(f(1))f′(1)=(3−2)·2=2 bulunur.','B');
 add(236,'Alan fonksiyonunda çarpım türevi','Türevin geometrik uygulaması','AYT-mat',79,
 'Köşeleri(0,0),(x,0),(x,f(x)) olan dik üçgenin alanını½xf(x) yazarak hem taban hem yüksekliğin değiştiğini ölçer.',
 ['Alan g(x)=xf(x)/2’dir;dik kenarlar x ve f(x)’tir.','Çarpım kuralı g′(x)=[f(x)+xf′(x)]/2 verir.'],
 ['x=3,f(3)=1,f′(3)=7 değerlerini yerine koy.','g′(3)=(1+3·7)/2=22/2=11 bulunur. Doğru seçenek E’dir;yalnız yükseklik türevi değil tabanın değişimi dehesaba katılır.'],
 'Alan türevini yalnız½x f′ yapmak x’in türevi1’den gelen f(x)/2 katkısını unutmak demektir.',
 'Değişen geometrik nicelik','Alan hem yatay uzunluk hem eğri yüksekliğiyle değişir;ürün türevinin iki terimi iki ayrı değişim kaynağını temsil eder.',
 'g(x)=xf(x)/2,f(2)=3,f′(2)=4 ise g′(2) kaçtır?',['4','9/2','5','11/2','6'],3,'g′(2)=[3+2·4]/2=11/2 bulunur.','E');
 add(237,'Teğet doğrusundan iki parametre','Teğet ve türev','AYT-mat',76,
 'y=3x+a doğrusunun eğimi3’ü f′(1)’e,1’deki6 ordinatını da doğrunun nokta koşuluna eşitlemeyi ölçer.',
 ['f′(x)=3x²−2x+b, dolayısıyla f′(1)=1+b’dir.','Teğet eğimi3 olduğundan b=2 olur;f(1)=b+4=6’dır. Bu değer eğrinin teğet noktasındaki ordinatını belirler.'],
 ['Teğet doğru P(1,6)’dan geçtiğinden6=3+a,a=3 bul.','a+b=3+2=5’tir;doğru seçenek B’dir. Eğim koşulu b’yi,noktadan geçme koşulu a’yı belirler.'],
 'a’yı doğrudan f(1) sanmak doğru sabit terimiyle noktanın ordinatını karıştırır;doğruda x=1 için3 deeklenir.',
 'İki teğet şartı','Bir doğru eğriye teğetse aynı noktayı paylaşmalı ve eğimleri eşit olmalıdır;iki şart ayrı parametreleri çözer.',
 'y=3x+a doğrusu(1,6)’dan geçiyorsa a kaçtır?',['1','2','3','4','5'],2,'6=3·1+a olduğundan a=3 bulunur.','B');
 add(238,'Eş başlangıçta toplamın ara değeri','Türev ve değer sıralaması','AYT-mat',81,
 'f=g+h ve f(1)=g(1)=h(1) eşitliklerinden ortak başlangıcın0 olduğunu çıkarıp türev işaretleriyle2’deki toplamı iki bileşen arasında sıralamayı ölçer.',
 ['Ortak değer t ise t=t+t olduğundan t=0’dır.','1–2 aralığında g′>0,h′<0 olduğundan g(2)>0,h(2)<0 olur.'],
 ['f(2)=g(2)+h(2),negatif h(2) nedeniyle g(2)’den küçüktür.','Pozitif g(2) eklenmesi f(2)’yi h(2)’den büyük yapar. h(2)<f(2)<g(2),cevap D’dir;f(2)’nin kendi işaretini belirlemek gerekmez.'],
 'Grafikte g′ daha yüksek diye doğrudan g(2)>h(2) demek başlangıç değerlerini atlar;burada eş başlangıç şartı bunu meşrulaştırır.',
 'Değişimden değer','Türev işareti başlangıçtan sonraki yönü verir;toplamın iki zıt işaretli değer arasında kalması basit cebirle tamamlanır.',
 'u>0,v<0 ise u+v hangi sıralamayı sağlar?',['u+v<u<v','v<u+v<u','u<v<u+v','u+v=v','u+v=u'],1,'u eklemek v’yi artırır,v eklemek u’yu azaltır. Bu nedenle v<u+v<u’dur.','D');
 add(239,'Her yerde artan kübikte diskriminant','Türevin işareti','AYT-mat',81,
 'f(−1)=0 koşulundan a=b+6 bulup ikinci derece türevin bütün gerçeklerde negatif olmaması için diskriminantı kullanmayı ölçer.',
 ['f(−1)=−a+b+6=0,a=b+6 verir.','f′=3ax²+2bx+1≥0 için baş katsayı pozitif ve4b²−12a≤0 olmalıdır.'],
 ['a=b+6 ile b²−3b−18=(b−6)(b+3)≤0, yani−3≤b≤6 bulunur.','Bu aralıkta a>0 sağlanır;uçlarda türev yalnız bir noktada0 olur ve artış sürer. Tam b değerleri toplam15,cevap C’dir.'],
 'Daima artan için f′>0’ı her noktada zorunlu saymak b=−3,6 uçlarını yanlış dışlar;izole sıfır türev artışı bozmaz.',
 'Küresel ikinci derece işaret','Türevin tüm gerçel doğru boyunca negatif olmaması,parabolünün x eksenini kesmemesi veya yalnız teğet olması demektir.',
 'b∈[−3,6] tam sayıysa değerler toplamı kaçtır?',['9','12','15','18','21'],2,'On tam sayı vardır. Aritmetik toplam(−3+6)·10/2=15 bulunur.','C');
 add(240,'İki yerel ekstremumda türev sıfırlığı','Çarpım türevi ve ekstremum','AYT-mat',79,
 'f ve x³f çarpımının−1’de ayrı ayrı türevlerinin sıfır olmasından önce m’yi,sonra f(−1)=0 koşulundan k’yı belirlemeyi ölçer.',
 ['f′=6x²−18x−m ve f′(−1)=24−m=0,m=24 verir.','g′=3x²f+x³f′ olduğundan−1’de3f(−1)−f′(−1)=0,f(−1)=0 olmalıdır.'],
 ['f(−1)=−2−9+24−k=13−k=0,k=13 bul.','k+m=37,cevap D’dir. Kontrol:f″(−1)=−30 ve g″(−1)=30 olduğundan gerçekten maksimum ve minimum oluşur.'],
 'Çarpım türevinde yalnız x³f′ terimini almak g’nin ekstremum koşulunu f ileaynı sayarak k’yı belirleyemez;3x²f katkısı zorunludur.',
 'Gerekli ve yeterli kontrol','Türev sıfır olması aday parametreleri verir;ikinci türevlerin sıfır olmaması gerçek yerel ekstremumu doğrular.',
 'f(−1)=0,f′(−1)=0 ve g=x³f ise g′(−1) kaçtır?',['−3','−1','0','1','3'],2,'g′(−1)=3f(−1)−f′(−1)=0’dır. Çarpım kuralının her iki terimi deayrı ayrı sıfırlanır.','D');
})();
